import type { BadgeProps, BadgeSize, BadgeVariant } from '../../../types/ui/badge.types';

const variantStyles: Record<BadgeVariant, string> = {
  default: 'bg-slate-100 text-slate-700 border border-slate-200/80',
  primary: 'bg-emerald-50 text-emerald-800 border border-emerald-200/80',
  success: 'bg-emerald-50 text-emerald-800 border border-emerald-200/80',
  warning: 'bg-amber-50 text-amber-800 border border-amber-200/80',
  danger: 'bg-rose-50 text-rose-800 border border-rose-200/80',
  info: 'bg-blue-50 text-blue-800 border border-blue-200/80',
  purple: 'bg-violet-50 text-violet-800 border border-violet-200/80',
};

const sizeStyles: Record<BadgeSize, string> = {
  xs: 'px-1.5 py-0.2 text-[9px]',
  sm: 'px-2 py-0.5 text-[10px]',
  md: 'px-2.5 py-1 text-[11px]',
};

export function Badge({ variant = 'default', size = 'sm', children, className = '', ...props }: BadgeProps) {
  return (
    <span
      className={`inline-flex items-center justify-center font-semibold rounded-full select-none transition-all ${sizeStyles[size]} ${variantStyles[variant]} ${className}`}
      {...props}
    >
      {children}
    </span>
  );
}

