import { useEffect } from 'react';

import { cn } from '../../../utils/ui/cn';

import { STACK_LAYER_CLASSES } from '../../../types/ui/layout.types';
import type { LayoutSidebarProps } from '../../../types/ui/layout.types';

export function LayoutSidebar({
  isOpen = false,
  onClose,
  width = 'w-64',
  collapsed = false,
  collapsedWidth = 'w-16',
  position = 'left',
  mobileMode = 'drawer',
  bordered = true,
  layer = 'sidebar',
  className = '',
  children,
}: LayoutSidebarProps) {
  // Handle escape key to close drawer when open
  useEffect(() => {
    if (!isOpen || !onClose) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  const desktopLayerClass = STACK_LAYER_CLASSES[layer] || 'z-30';
  const drawerLayerClass = STACK_LAYER_CLASSES.drawer;

  const currentWidth = collapsed ? collapsedWidth : width;

  return (
    <aside
      className={cn(
        // Base structure
        'flex flex-col h-full min-h-0 shrink-0 transition-all duration-200 ease-out',
        'bg-white dark:bg-slate-900 transition-colors',

        // Border
        bordered &&
          (position === 'left'
            ? 'border-r border-slate-200 dark:border-slate-800'
            : 'border-l border-slate-200 dark:border-slate-800'),

        // Desktop behavior
        'hidden md:flex',
        desktopLayerClass,
        currentWidth,

        // Mobile drawer behavior
        mobileMode === 'drawer' && [
          isOpen
            ? cn(
                '!flex fixed inset-y-0 w-[85vw] max-w-xs shadow-2xl translate-x-0',
                drawerLayerClass,
                position === 'left' ? 'left-0' : 'right-0'
              )
            : cn(
                'max-md:fixed max-md:inset-y-0 max-md:pointer-events-none',
                position === 'left'
                  ? 'max-md:-translate-x-full max-md:left-0'
                  : 'max-md:translate-x-full max-md:right-0'
              ),
        ],

        className
      )}
    >
      {children}
    </aside>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { LayoutSidebarProps } from '../../../types/ui/layout.types';
