import { forwardRef, useEffect, useId, useMemo, useRef, useState } from 'react';
import { Check, ChevronDown, Search, X } from 'lucide-react';

import { FieldWrapper } from '../field-wrapper';

import { cn } from '../../../../utils/ui/cn';

import type { SelectOption, SelectProps } from '../../../../types/ui/field/select.types';

export const Select = forwardRef<HTMLButtonElement, SelectProps>(
  (
    {
      options,
      value,
      onChange,
      placeholder = 'Pilih opsi...',
      label,
      error,
      helperText,
      hint,
      required,
      optional,
      disabled,
      size = 'md',
      layout = 'vertical',
      searchable = false,
      searchPlaceholder = 'Cari opsi...',
      clearable = false,
      emptyText = 'Tidak ada opsi tersedia',
      className,
      wrapperClassName,
    },
    ref
  ) => {
    const generatedId = useId();
    const containerRef = useRef<HTMLDivElement>(null);
    const searchInputRef = useRef<HTMLInputElement>(null);

    const [isOpen, setIsOpen] = useState(false);
    const [searchQuery, setSearchQuery] = useState('');

    const normalizedOptions: SelectOption[] = useMemo(() => {
      return options.map((opt) => (typeof opt === 'string' ? { label: opt, value: opt } : opt));
    }, [options]);

    const selectedOption = useMemo(() => {
      return normalizedOptions.find((opt) => opt.value === value);
    }, [normalizedOptions, value]);

    const filteredOptions = useMemo(() => {
      if (!searchable || !searchQuery.trim()) return normalizedOptions;
      const q = searchQuery.toLowerCase();
      return normalizedOptions.filter(
        (opt) => opt.label.toLowerCase().includes(q) || (opt.description && opt.description.toLowerCase().includes(q))
      );
    }, [normalizedOptions, searchable, searchQuery]);

    useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
        if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
          setIsOpen(false);
          setSearchQuery('');
        }
      };

      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    useEffect(() => {
      if (isOpen && searchable) {
        setTimeout(() => searchInputRef.current?.focus(), 50);
      }
    }, [isOpen, searchable]);

    const handleSelect = (option: SelectOption) => {
      if (option.disabled) return;
      onChange?.(option.value);
      setIsOpen(false);
      setSearchQuery('');
    };

    const handleClear = (e: React.MouseEvent) => {
      e.stopPropagation();
      onChange?.('');
    };

    const sizeClasses = {
      sm: 'py-1.5 px-3 text-xs',
      md: 'py-2.5 px-3.5 text-sm',
      lg: 'py-3 px-4 text-base',
    }[size];

    const selectNode = (
      <div ref={containerRef} className="relative w-full">
        <button
          ref={ref}
          id={generatedId}
          type="button"
          onClick={() => !disabled && setIsOpen((prev) => !prev)}
          disabled={disabled}
          className={cn(
            'w-full flex items-center justify-between text-left transition-colors rounded-lg focus:outline-none cursor-pointer',
            sizeClasses,
            error
              ? 'bg-rose-50/20 border border-rose-300 focus:border-rose-500 focus:ring-1 focus:ring-rose-500 text-rose-900'
              : 'bg-white hover:border-slate-400 focus:border-emerald-600 focus:ring-1 focus:ring-emerald-600 border border-slate-300',
            disabled && 'opacity-60 bg-slate-50/80 cursor-not-allowed border-slate-200',
            className
          )}
          aria-haspopup="listbox"
          aria-expanded={isOpen}
        >
          <div className="flex items-center gap-2 truncate">
            {selectedOption ? (
              <>
                {selectedOption.icon && <span className="shrink-0">{selectedOption.icon}</span>}
                <span className="text-slate-800 font-medium truncate">{selectedOption.label}</span>
              </>
            ) : (
              <span className="text-slate-400 select-none truncate">{placeholder}</span>
            )}
          </div>

          <div className="flex items-center gap-1.5 ml-2 shrink-0">
            {clearable && selectedOption && !disabled && (
              <span
                role="button"
                onClick={handleClear}
                className="p-0.5 rounded-md text-slate-400 hover:text-slate-600 hover:bg-slate-200/60 transition-colors cursor-pointer"
                aria-label="Bersihkan pilihan"
              >
                <X className="w-3.5 h-3.5" />
              </span>
            )}
            <ChevronDown
              className={cn('w-4 h-4 text-slate-400 transition-transform duration-200', isOpen && 'rotate-180')}
            />
          </div>
        </button>

        {isOpen && (
          <div className="absolute z-50 w-full mt-1.5 bg-white border border-slate-200 rounded-lg shadow-xl overflow-hidden animate-in fade-in zoom-in-95 duration-100 max-h-64 flex flex-col">
            {searchable && (
              <div className="p-2 border-b border-slate-100">
                <div className="relative flex items-center">
                  <Search className="w-3.5 h-3.5 absolute left-2.5 text-slate-400 pointer-events-none" />
                  <input
                    ref={searchInputRef}
                    type="text"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    placeholder={searchPlaceholder}
                    className="w-full pl-8 pr-3 py-1.5 text-xs bg-slate-50 border border-slate-200 rounded-lg text-slate-800 focus:outline-none focus:border-emerald-500 focus:bg-white"
                  />
                </div>
              </div>
            )}

            <div className="overflow-y-auto p-1 max-h-52">
              {filteredOptions.length === 0 ? (
                <div className="px-4 py-3 text-xs text-slate-500 text-center select-none">{emptyText}</div>
              ) : (
                <ul role="listbox">
                  {filteredOptions.map((option) => {
                    const isSelected = option.value === value;

                    return (
                      <li
                        key={option.value}
                        role="option"
                        aria-selected={isSelected}
                        onClick={() => handleSelect(option)}
                        className={cn(
                          'flex items-center justify-between px-3 py-2 text-xs md:text-sm rounded-lg cursor-pointer transition-colors select-none',
                          isSelected
                            ? 'bg-emerald-50 text-emerald-900 font-medium'
                            : 'text-slate-700 hover:bg-slate-100 hover:text-slate-900',
                          option.disabled && 'opacity-40 cursor-not-allowed hover:bg-transparent'
                        )}
                      >
                        <div className="flex flex-col truncate">
                          <span className="flex items-center gap-2 truncate">
                            {option.icon && <span className="shrink-0">{option.icon}</span>}
                            <span className="truncate">{option.label}</span>
                          </span>
                          {option.description && (
                            <span className="text-[11px] text-slate-400 font-normal truncate">
                              {option.description}
                            </span>
                          )}
                        </div>

                        {isSelected && <Check className="w-4 h-4 text-emerald-600 shrink-0 ml-2" />}
                      </li>
                    );
                  })}
                </ul>
              )}
            </div>
          </div>
        )}
      </div>
    );

    if (label || error || helperText || hint) {
      return (
        <FieldWrapper
          htmlFor={generatedId}
          label={label}
          error={error}
          helperText={helperText}
          hint={hint}
          required={required}
          optional={optional}
          disabled={disabled}
          size={size}
          layout={layout}
          className={wrapperClassName}
        >
          {selectNode}
        </FieldWrapper>
      );
    }

    return selectNode;
  }
);

Select.displayName = 'Select';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { SelectOption, SelectProps } from '../../../../types/ui/field/select.types';
