import { forwardRef, useId, useState } from 'react';
import { Eye, EyeOff, X } from 'lucide-react';

import { FieldWrapper } from '../field-wrapper';

import { cn } from '../../../../utils/ui/cn';

import type { TextFieldProps } from '../../../../types/ui/field/textField.types';

export const TextField = forwardRef<HTMLInputElement, TextFieldProps>(
  (
    {
      type = 'text',
      id: customId,
      name,
      value,
      defaultValue,
      onChange,
      placeholder,
      disabled,
      readOnly,
      required,
      optional,
      label,
      error,
      helperText,
      hint,
      size = 'md',
      layout = 'vertical',
      leftIcon,
      rightIcon,
      prefixText,
      suffixText,
      clearable,
      onClear,
      isPasswordToggle = true,
      wrapperClassName,
      inputWrapperClassName,
      className,
      ...props
    },
    ref
  ) => {
    const generatedId = useId();
    const inputId = customId || generatedId;

    const [showPassword, setShowPassword] = useState(false);
    const isPassword = type === 'password';
    const effectiveType = isPassword && showPassword ? 'text' : type;

    const hasValue = Boolean(value !== undefined && String(value).length > 0);

    const sizeClasses = {
      sm: 'py-1.5 text-xs min-h-[32px]',
      md: 'py-2 text-sm min-h-[38px]',
      lg: 'py-2.5 text-base min-h-[44px]',
    }[size];

    const paddingClasses = {
      sm: cn(
        prefixText ? 'pl-2' : leftIcon ? 'pl-1.5' : 'pl-2.5',
        suffixText ? 'pr-2' : rightIcon || (isPassword && isPasswordToggle) || (clearable && hasValue) ? 'pr-1.5' : 'pr-2.5'
      ),
      md: cn(
        prefixText ? 'pl-2.5' : leftIcon ? 'pl-2' : 'pl-3',
        suffixText ? 'pr-2.5' : rightIcon || (isPassword && isPasswordToggle) || (clearable && hasValue) ? 'pr-2' : 'pr-3'
      ),
      lg: cn(
        prefixText ? 'pl-3' : leftIcon ? 'pl-2.5' : 'pl-3.5',
        suffixText ? 'pr-3' : rightIcon || (isPassword && isPasswordToggle) || (clearable && hasValue) ? 'pr-2.5' : 'pr-3.5'
      ),
    }[size];

    const iconSizeClasses = {
      sm: 'w-3.5 h-3.5',
      md: 'w-4 h-4',
      lg: 'w-5 h-5',
    }[size];

    const inputNode = (
      <div
        className={cn(
          'group/input-field relative flex items-center w-full rounded-lg transition-colors duration-150 overflow-hidden',
          'bg-white border',
          error
            ? 'border-rose-300 bg-rose-50/20 focus-within:border-rose-500 focus-within:ring-1 focus-within:ring-rose-500'
            : 'border-slate-300 hover:border-slate-400 focus-within:border-emerald-600 focus-within:ring-1 focus-within:ring-emerald-600',
          disabled && 'opacity-60 bg-slate-50/80 cursor-not-allowed border-slate-200',
          inputWrapperClassName
        )}
      >
        {prefixText && (
          <span
            className={cn(
              'inline-flex items-center justify-center self-stretch shrink-0 font-mono font-medium select-none transition-colors',
              'border-r border-slate-200 bg-slate-50 text-slate-600 group-focus-within/input-field:border-emerald-600/40 group-focus-within/input-field:bg-emerald-50/40 group-focus-within/input-field:text-emerald-700',
              size === 'sm' ? 'px-2.5 text-xs' : size === 'lg' ? 'px-3.5 text-sm' : 'px-3 text-xs'
            )}
          >
            {prefixText}
          </span>
        )}

        {leftIcon && !prefixText && (
          <div className="pl-2.5 flex items-center pointer-events-none text-slate-400 group-focus-within/input-field:text-emerald-600 transition-colors shrink-0">
            <span className={iconSizeClasses}>{leftIcon}</span>
          </div>
        )}

        <input
          ref={ref}
          id={inputId}
          name={name}
          type={effectiveType}
          value={value}
          defaultValue={defaultValue}
          onChange={onChange}
          placeholder={placeholder}
          disabled={disabled}
          readOnly={readOnly}
          required={required}
          className={cn(
            'w-full flex-1 min-w-0 bg-transparent border-0 outline-none focus:outline-none focus:ring-0 text-slate-800 placeholder:text-slate-400 font-medium',
            sizeClasses,
            paddingClasses,
            disabled && 'cursor-not-allowed',
            className
          )}
          {...props}
        />

        {/* Right Controls: Clear button, Password toggle, rightIcon */}
        {((clearable && hasValue && onClear && !disabled && !readOnly) ||
          (isPassword && isPasswordToggle && !disabled) ||
          (rightIcon && !isPassword)) && (
          <div className="flex items-center gap-1 pr-2 shrink-0">
            {clearable && hasValue && onClear && !disabled && !readOnly && (
              <button
                type="button"
                onClick={onClear}
                className="p-1 rounded-md text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors cursor-pointer"
                aria-label="Bersihkan input"
              >
                <X className={iconSizeClasses} />
              </button>
            )}

            {isPassword && isPasswordToggle && !disabled && (
              <button
                type="button"
                onClick={() => setShowPassword((prev) => !prev)}
                className="p-1 rounded-md text-slate-400 hover:text-slate-600 hover:bg-slate-100 transition-colors cursor-pointer"
                aria-label={showPassword ? 'Sembunyikan password' : 'Tampilkan password'}
              >
                {showPassword ? <EyeOff className={iconSizeClasses} /> : <Eye className={iconSizeClasses} />}
              </button>
            )}

            {rightIcon && !isPassword && !clearable && (
              <div className="pointer-events-none text-slate-400 group-focus-within/input-field:text-emerald-600 transition-colors">
                <span className={iconSizeClasses}>{rightIcon}</span>
              </div>
            )}
          </div>
        )}

        {suffixText && (
          <span
            className={cn(
              'inline-flex items-center justify-center self-stretch shrink-0 font-mono font-medium select-none transition-colors',
              'border-l border-slate-200 bg-slate-50 text-slate-600 group-focus-within/input-field:border-emerald-600/40 group-focus-within/input-field:bg-emerald-50/40 group-focus-within/input-field:text-emerald-700',
              size === 'sm' ? 'px-2.5 text-xs' : size === 'lg' ? 'px-3.5 text-sm' : 'px-3 text-xs'
            )}
          >
            {suffixText}
          </span>
        )}
      </div>
    );

    if (label || error || helperText || hint) {
      return (
        <FieldWrapper
          htmlFor={inputId}
          label={label}
          error={error}
          helperText={helperText}
          hint={hint}
          required={required}
          optional={optional}
          disabled={disabled}
          size={size}
          layout={layout}
          className={wrapperClassName}
        >
          {inputNode}
        </FieldWrapper>
      );
    }

    return inputNode;
  }
);

TextField.displayName = 'TextField';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { TextFieldProps } from '../../../../types/ui/field/textField.types';
