import type { ReactNode } from 'react';
import {
  Check,
  Columns2,
  FileCode,
  FolderTree,
  Moon,
  Sun,
  X,
} from 'lucide-react';

import { Badge } from '../badge';
import { Button } from '../button';

import { cn } from '../../../utils/ui/cn';

import type { CodeEditorTheme, CodeEditorViewMode } from '../../../types/ui/code-editor.types';

export function FullScreenHeader({
  title,
  subtitle,
  badge,
  language = 'json',
  isValidJson,
  viewMode,
  onViewModeChange,
  theme,
  onToggleTheme,
  readOnly = false,
  onSave,
  onClose,
}: FullScreenHeaderProps) {
  const isDark = theme === 'dark';

  return (
    <div
      className={cn(
        'flex flex-wrap items-center justify-between gap-3 px-4 py-2.5 border-b shrink-0 select-none transition-colors',
        isDark ? 'bg-slate-900 border-slate-800 text-white' : 'bg-slate-100 border-slate-200 text-slate-900'
      )}
    >
      {/* Title & Metadata */}
      <div className="flex items-center gap-3">
        <div
          className={cn(
            'w-8 h-8 rounded-xl flex items-center justify-center border transition-colors',
            isDark
              ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'
              : 'bg-emerald-100 text-emerald-700 border-emerald-200'
          )}
        >
          <FileCode className="w-4 h-4" />
        </div>
        <div>
          <div className="flex items-center gap-2">
            <span className="font-semibold text-sm">{title}</span>
            {badge}
            {language === 'json' && (
              <Badge
                variant={isValidJson ? 'success' : 'danger'}
                size="xs"
                className="font-mono text-[10px]"
              >
                {isValidJson ? 'Valid JSON' : 'Syntax Error'}
              </Badge>
            )}
          </div>
          {subtitle && (
            <p className={cn('text-xs', isDark ? 'text-slate-400' : 'text-slate-500')}>{subtitle}</p>
          )}
        </div>
      </div>

      {/* View Mode Switcher (Code | Tree | Split) */}
      {language === 'json' && (
        <div
          className={cn(
            'flex items-center p-0.5 rounded-xl border text-xs transition-colors',
            isDark ? 'bg-slate-800/80 border-slate-700/60' : 'bg-slate-200/80 border-slate-300/80'
          )}
        >
          <button
            type="button"
            onClick={() => onViewModeChange('code')}
            className={cn(
              'flex items-center gap-1.5 px-3 py-1 rounded-lg transition-colors cursor-pointer',
              viewMode === 'code'
                ? isDark
                  ? 'bg-slate-700 text-white font-semibold shadow-xs'
                  : 'bg-white text-slate-900 font-semibold shadow-xs'
                : isDark
                ? 'text-slate-400 hover:text-white'
                : 'text-slate-600 hover:text-slate-900'
            )}
            title="Raw code view"
          >
            <FileCode className="w-3.5 h-3.5" />
            <span>Code</span>
          </button>
          <button
            type="button"
            onClick={() => onViewModeChange('tree')}
            className={cn(
              'flex items-center gap-1.5 px-3 py-1 rounded-lg transition-colors cursor-pointer',
              viewMode === 'tree'
                ? isDark
                  ? 'bg-slate-700 text-white font-semibold shadow-xs'
                  : 'bg-white text-slate-900 font-semibold shadow-xs'
                : isDark
                ? 'text-slate-400 hover:text-white'
                : 'text-slate-600 hover:text-slate-900'
            )}
            title="Interactive tree view"
          >
            <FolderTree className="w-3.5 h-3.5" />
            <span>Tree</span>
          </button>
          <button
            type="button"
            onClick={() => onViewModeChange('split')}
            className={cn(
              'flex items-center gap-1.5 px-3 py-1 rounded-lg transition-colors cursor-pointer',
              viewMode === 'split'
                ? 'bg-emerald-600 text-white font-semibold shadow-xs'
                : isDark
                ? 'text-slate-400 hover:text-white'
                : 'text-slate-600 hover:text-slate-900'
            )}
            title="Side-by-side split view (Code + Tree)"
          >
            <Columns2 className="w-3.5 h-3.5" />
            <span>Split View</span>
          </button>
        </div>
      )}

      {/* Action Buttons & Theme Switcher */}
      <div className="flex items-center gap-2">
        {/* Theme Toggle Button */}
        <button
          type="button"
          onClick={onToggleTheme}
          className={cn(
            'p-1.5 rounded-lg border transition-colors cursor-pointer flex items-center justify-center',
            isDark
              ? 'bg-slate-800 border-slate-700 text-amber-400 hover:bg-slate-700 hover:text-amber-300'
              : 'bg-white border-slate-300 text-slate-600 hover:bg-slate-100 hover:text-slate-900'
          )}
          title={isDark ? 'Switch to Light Mode' : 'Switch to Dark Mode'}
        >
          {isDark ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
        </button>

        {!readOnly && onSave && (
          <Button
            variant="primary"
            size="sm"
            onClick={onSave}
            leftIcon={<Check className="w-4 h-4" />}
            className="bg-emerald-600 hover:bg-emerald-500 text-white"
          >
            Save
          </Button>
        )}

        <Button
          variant="outline"
          size="sm"
          onClick={onClose}
          leftIcon={<X className="w-4 h-4" />}
          className={cn(
            isDark
              ? 'bg-slate-800 border-slate-700 text-slate-200 hover:bg-slate-700 hover:text-white'
              : 'bg-white border-slate-300 text-slate-700 hover:bg-slate-100'
          )}
        >
          Close
        </Button>
      </div>
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================

export interface FullScreenHeaderProps {
  title: ReactNode;
  subtitle?: ReactNode;
  badge?: ReactNode;
  language?: string;
  isValidJson: boolean;
  viewMode: CodeEditorViewMode;
  onViewModeChange: (mode: CodeEditorViewMode) => void;
  theme: CodeEditorTheme;
  onToggleTheme: () => void;
  readOnly?: boolean;
  onSave?: () => void;
  onClose: () => void;
}
