import { ActionBar } from './ActionBar';
import { ContainerContent } from './ContainerContent';
import { ContainerFooter } from './ContainerFooter';
import { ContainerHeader } from './ContainerHeader';

import { cn } from '../../../utils/ui/cn';

import type {
  ContainerPadding,
  ContainerProps,
  ContainerSize,
  ContainerVariant,
} from '../../../types/ui/container.types';

const sizeClasses: Record<ContainerSize, string> = {
  sm: 'max-w-screen-sm',
  md: 'max-w-screen-md',
  lg: 'max-w-screen-lg',
  xl: 'max-w-screen-xl',
  '2xl': 'max-w-screen-2xl',
  full: 'w-full',
};

const paddingClasses: Record<ContainerPadding, string> = {
  none: 'p-0',
  small: 'p-3 sm:p-4',
  medium: 'p-4 sm:p-6',
  large: 'p-6 sm:p-8',
};

const variantClasses: Record<ContainerVariant, string> = {
  default: '',
  card: 'bg-white border border-slate-200/90 rounded-2xl shadow-xs text-slate-900 overflow-hidden',
  elevated: 'bg-white border border-slate-200/80 rounded-2xl shadow-md text-slate-900 overflow-hidden',
  bordered: 'bg-white border border-slate-200 rounded-xl text-slate-900 overflow-hidden',
  flat: 'bg-slate-50/90 border border-slate-200/80 rounded-xl text-slate-900 overflow-hidden',
  ghost: 'bg-transparent text-slate-900',
};

export function Container({
  size = 'full',
  padding = 'none',
  variant = 'default',
  centered = true,
  className = '',
  children,
  ...props
}: ContainerProps) {
  return (
    <div
      className={cn(
        'w-full flex flex-col transition-colors',
        sizeClasses[size],
        paddingClasses[padding],
        variantClasses[variant],
        centered && size !== 'full' && 'mx-auto',
        className
      )}
      {...props}
    >
      {children}
    </div>
  );
}

// Compound subcomponents
Container.ActionBar = ActionBar;
Container.Header = ContainerHeader;
Container.Content = ContainerContent;
Container.Footer = ContainerFooter;

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type {
  ActionBarProps,
  ContainerContentProps,
  ContainerFooterProps,
  ContainerHeaderProps,
  ContainerProps,
} from '../../../types/ui/container.types';
