import type { RefObject } from 'react';

import { cn } from '../../../utils/ui/cn';

import type { CodeEditorTheme } from '../../../types/ui/code-editor.types';

export function CodeGutter({
  gutterRef,
  lineNumbers,
  theme = 'dark',
  className = '',
}: CodeGutterProps) {
  const isDark = theme === 'dark';

  return (
    <div
      ref={gutterRef}
      aria-hidden="true"
      className={cn(
        'w-12 py-3 border-r text-right pr-2 font-mono text-xs select-none overflow-hidden shrink-0 leading-relaxed transition-colors',
        isDark
          ? 'bg-slate-950 border-slate-800 text-slate-600'
          : 'bg-slate-100 border-slate-200 text-slate-400',
        className
      )}
    >
      {lineNumbers.map((num) => (
        <div key={num} className="h-5">
          {num}
        </div>
      ))}
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================

export interface CodeGutterProps {
  gutterRef: RefObject<HTMLDivElement | null>;
  lineNumbers: number[];
  theme?: CodeEditorTheme;
  className?: string;
}
