import type { ReactNode } from 'react';

/**
 * Standardized stack layer tokens for layout hierarchy and z-index ordering.
 * Guarantees consistent layering across all components and overlays.
 */
export type LayoutStackLayer =
  | 'base'      // 0 - Page content
  | 'sticky'    // 10 - In-page sticky toolbars or headers
  | 'header'    // 20 - Main application top header
  | 'sidebar'   // 30 - Desktop persistent navigation sidebar
  | 'backdrop'  // 40 - Backdrop overlay (covers header and sidebar)
  | 'drawer'    // 50 - Mobile sidebar / slide-over drawer (sits on top of backdrop)
  | 'modal'     // 60 - Dialogs, Modals, Fullscreen editors
  | 'popover'   // 70 - Dropdowns, Popovers, Select menus, Tooltips
  | 'toast'     // 80 - Floating toast notifications
  | 'loading';  // 100 - Global full-screen blocker loading (topmost layer)

export const STACK_LAYER_Z_INDEX: Record<LayoutStackLayer, number> = {
  base: 0,
  sticky: 10,
  header: 20,
  sidebar: 30,
  backdrop: 40,
  drawer: 50,
  modal: 60,
  popover: 70,
  toast: 80,
  loading: 100,
} as const;

export const STACK_LAYER_CLASSES: Record<LayoutStackLayer, string> = {
  base: 'z-0',
  sticky: 'z-10',
  header: 'z-20',
  sidebar: 'z-30',
  backdrop: 'z-40',
  drawer: 'z-50',
  modal: 'z-[60]',
  popover: 'z-[70]',
  toast: 'z-[80]',
  loading: 'z-[100]',
} as const;

export type LayoutTheme = 'light' | 'dark';

export interface LayoutProps {
  theme?: LayoutTheme;
  fullScreen?: boolean;
  className?: string;
  children?: ReactNode;
}

export interface LayoutHeaderProps {
  height?: string;
  sticky?: boolean;
  bordered?: boolean;
  layer?: LayoutStackLayer;
  className?: string;
  children?: ReactNode;
}

export interface LayoutBodyProps {
  className?: string;
  children?: ReactNode;
}

export interface LayoutSidebarProps {
  isOpen?: boolean;
  onClose?: () => void;
  width?: string;
  collapsed?: boolean;
  collapsedWidth?: string;
  position?: 'left' | 'right';
  mobileMode?: 'drawer' | 'hidden';
  bordered?: boolean;
  layer?: LayoutStackLayer;
  className?: string;
  children?: ReactNode;
}

export interface LayoutContentProps {
  padded?: boolean;
  className?: string;
  children?: ReactNode;
}

export interface LayoutBackdropProps {
  visible?: boolean;
  onClick?: () => void;
  blur?: boolean;
  scope?: 'full' | 'body';
  layer?: LayoutStackLayer;
  className?: string;
  children?: ReactNode;
}

export interface LayoutLoadingProps {
  visible?: boolean;
  message?: ReactNode;
  description?: ReactNode;
  variant?: 'spinner' | 'bar' | 'overlay';
  progress?: number;
  blur?: boolean;
  layer?: LayoutStackLayer;
  customIcon?: ReactNode;
  className?: string;
}

export interface StackLayerProps {
  layer?: LayoutStackLayer;
  zIndex?: number;
  fixed?: boolean;
  absolute?: boolean;
  fullScreen?: boolean;
  className?: string;
  children?: ReactNode;
}
