import type { ReactNode } from 'react';
import {
  AlertCircle,
  AlertTriangle,
  CheckCircle2,
  Info,
  Loader2,
  X,
} from 'lucide-react';

import { cn } from '../../../utils/ui/cn';

import type {
  ToastItemProps,
  ToastTheme,
  ToastType,
} from '../../../types/ui/toast.types';

export function ToastItem({
  toast,
  index,
  total: _total,
  isExpanded,
  position,
  onDismiss,
  theme = 'colored',
  showProgress = true,
  className = '',
}: ToastItemProps) {
  const effectiveTheme: ToastTheme = toast.theme || theme;
  const isColored = effectiveTheme === 'colored';
  const isDark = effectiveTheme === 'dark';
  const type = toast.type || 'default';
  const title = toast.title || toast.msg;
  const hasDescription = Boolean(toast.description);
  const duration = toast.duration ?? toast.durationMs ?? 4000;
  const isFiniteDuration = duration !== Infinity && duration > 0;

  // Stacking calculation
  // index 0 is frontmost (newest toast)
  const isTopPosition = position.startsWith('top');
  const stackDirection = isTopPosition ? 1 : -1;

  // Visual transforms when stacked vs expanded
  const scale = isExpanded ? 1 : Math.max(0.85, 1 - index * 0.05);
  const translateY = isExpanded ? 0 : index * 10 * stackDirection;
  const opacity = isExpanded
    ? 1
    : index > 2
    ? 0
    : Math.max(0.65, 1 - index * 0.15);
  const zIndex = 50 - index;
  const isVisible = isExpanded || index <= 2;

  if (!isVisible) {
    return null;
  }

  const variantStyles = getToastVariantStyles(type, effectiveTheme);

  return (
    <div
      style={{
        zIndex,
        transform: `translateY(${translateY}px) scale(${scale})`,
        opacity,
        transition: 'all 280ms cubic-bezier(0.16, 1, 0.3, 1)',
      }}
      className={cn(
        'relative overflow-hidden w-full max-w-md rounded-2xl border transition-all select-none pointer-events-auto',
        isExpanded ? 'mb-2.5 hover:scale-[1.01]' : 'absolute inset-x-0 top-0',
        variantStyles.card,
        className,
        toast.className
      )}
    >
      {/* Subtle Shimmer Sheen for Colored Theme */}
      {isColored && (
        <div
          className="absolute inset-0 z-0 pointer-events-none opacity-20 bg-gradient-to-r from-transparent via-white to-transparent"
          style={{
            animation: 'toast-shimmer 2.8s ease-in-out infinite',
          }}
        />
      )}

      {/* Main Toast Content Body */}
      <div
        className={cn(
          'relative z-10 px-4 py-3 sm:py-3.5 flex gap-3.5',
          hasDescription ? 'items-start' : 'items-center'
        )}
      >
        {/* Status Icon */}
        <div
          className={cn(
            'flex items-center justify-center w-8 h-8 rounded-xl shrink-0 border shadow-2xs transition-colors',
            hasDescription && 'mt-0.5',
            variantStyles.iconContainer
          )}
        >
          {toast.icon ? toast.icon : getToastIcon(type, effectiveTheme)}
        </div>

        {/* Text Content: Title & Description */}
        <div className="flex-1 min-w-0 pr-1">
          {title && (
            <div
              className={cn(
                'font-semibold text-[13px] sm:text-sm leading-snug tracking-[-0.01em]',
                isColored || isDark ? 'text-white' : 'text-slate-900'
              )}
            >
              {title}
            </div>
          )}

          {toast.description && (
            <div
              className={cn(
                'text-xs mt-1 leading-relaxed line-clamp-2 font-normal',
                isColored
                  ? 'text-white/90'
                  : isDark
                  ? 'text-slate-400'
                  : 'text-slate-500'
              )}
            >
              {toast.description}
            </div>
          )}
        </div>

        {/* Action Button */}
        {toast.action && (
          <button
            type="button"
            onClick={(e) => {
              toast.action?.onClick(e);
              onDismiss(toast.id || '');
            }}
            className={cn(
              'shrink-0 text-xs font-semibold px-2.5 py-1 rounded-lg border transition-all cursor-pointer shadow-2xs',
              hasDescription ? 'self-start mt-0.5' : 'self-center',
              variantStyles.actionButton
            )}
          >
            {toast.action.label}
          </button>
        )}

        {/* Close Button */}
        {toast.dismissible !== false && (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              onDismiss(toast.id || '');
            }}
            className={cn(
              'w-7 h-7 flex items-center justify-center rounded-lg transition-all shrink-0 cursor-pointer border border-transparent',
              hasDescription ? 'self-start mt-0.5' : 'self-center',
              isColored
                ? 'text-white/80 hover:text-white hover:bg-white/20 active:bg-white/30'
                : isDark
                ? 'text-slate-400 hover:text-white hover:bg-slate-800/90 hover:border-slate-700/60 active:bg-slate-700'
                : 'text-slate-400 hover:text-slate-700 hover:bg-slate-100 hover:border-slate-200 active:bg-slate-200/80'
            )}
            aria-label="Tutup notifikasi"
          >
            <X className="w-3.5 h-3.5 stroke-[2.25]" />
          </button>
        )}
      </div>

      {/* Sleek Bottom Countdown Progress Bar */}
      {showProgress && isFiniteDuration && (
        <div
          className={cn(
            'absolute bottom-0 inset-x-0 h-[2.5px] overflow-hidden pointer-events-none',
            isColored
              ? 'bg-black/15'
              : isDark
              ? 'bg-slate-800/60'
              : 'bg-slate-100/90'
          )}
        >
          <div
            className={cn('h-full w-full', variantStyles.progressBar)}
            style={{
              animation: `toast-progress ${duration}ms linear forwards`,
              transformOrigin: 'left',
            }}
          />
        </div>
      )}
    </div>
  );
}

// ============================================================================
// HELPERS
// ============================================================================

function getToastIcon(type: ToastType, theme: ToastTheme): ReactNode {
  const isColored = theme === 'colored';

  if (isColored) {
    switch (type) {
      case 'success':
        return <CheckCircle2 className="w-4 h-4 text-white" />;
      case 'error':
        return <AlertCircle className="w-4 h-4 text-white" />;
      case 'warning':
        return <AlertTriangle className="w-4 h-4 text-white" />;
      case 'info':
        return <Info className="w-4 h-4 text-white" />;
      case 'loading':
        return <Loader2 className="w-4 h-4 text-white animate-spin" />;
      default:
        return <Info className="w-4 h-4 text-white" />;
    }
  }

  switch (type) {
    case 'success':
      return <CheckCircle2 className="w-4 h-4 text-emerald-500" />;
    case 'error':
      return <AlertCircle className="w-4 h-4 text-rose-500" />;
    case 'warning':
      return <AlertTriangle className="w-4 h-4 text-amber-500" />;
    case 'info':
      return <Info className="w-4 h-4 text-sky-500" />;
    case 'loading':
      return <Loader2 className="w-4 h-4 text-violet-500 animate-spin" />;
    default:
      return <Info className="w-4 h-4 text-slate-400" />;
  }
}

interface ToastVariantStyles {
  card: string;
  iconContainer: string;
  actionButton: string;
  progressBar: string;
}

function getToastVariantStyles(type: ToastType, theme: ToastTheme): ToastVariantStyles {
  if (theme === 'colored') {
    switch (type) {
      case 'success':
        return {
          card: 'bg-emerald-600 text-white border-emerald-500 shadow-xl shadow-emerald-950/25',
          iconContainer: 'bg-white/20 border-white/30 text-white',
          actionButton:
            'bg-white hover:bg-emerald-50 text-emerald-950 font-bold border-white/90 active:scale-[0.98]',
          progressBar: 'bg-white/80',
        };
      case 'error':
        return {
          card: 'bg-rose-600 text-white border-rose-500 shadow-xl shadow-rose-950/25',
          iconContainer: 'bg-white/20 border-white/30 text-white',
          actionButton:
            'bg-white hover:bg-rose-50 text-rose-950 font-bold border-white/90 active:scale-[0.98]',
          progressBar: 'bg-white/80',
        };
      case 'warning':
        return {
          card: 'bg-amber-600 text-white border-amber-500 shadow-xl shadow-amber-950/25',
          iconContainer: 'bg-white/20 border-white/30 text-white',
          actionButton:
            'bg-white hover:bg-amber-50 text-amber-950 font-bold border-white/90 active:scale-[0.98]',
          progressBar: 'bg-white/80',
        };
      case 'info':
        return {
          card: 'bg-sky-600 text-white border-sky-500 shadow-xl shadow-sky-950/25',
          iconContainer: 'bg-white/20 border-white/30 text-white',
          actionButton:
            'bg-white hover:bg-sky-50 text-sky-950 font-bold border-white/90 active:scale-[0.98]',
          progressBar: 'bg-white/80',
        };
      case 'loading':
        return {
          card: 'bg-indigo-600 text-white border-indigo-500 shadow-xl shadow-indigo-950/25',
          iconContainer: 'bg-white/20 border-white/30 text-white',
          actionButton:
            'bg-white hover:bg-indigo-50 text-indigo-950 font-bold border-white/90 active:scale-[0.98]',
          progressBar: 'bg-white/80',
        };
      default:
        return {
          card: 'bg-slate-800 text-white border-slate-700 shadow-xl shadow-black/30',
          iconContainer: 'bg-white/15 border-white/20 text-white',
          actionButton:
            'bg-white hover:bg-slate-100 text-slate-900 font-bold border-white/90 active:scale-[0.98]',
          progressBar: 'bg-white/80',
        };
    }
  }

  if (theme === 'dark') {
    switch (type) {
      case 'success':
        return {
          card: 'bg-slate-900/95 text-slate-100 shadow-2xl shadow-black/50 backdrop-blur-xl border-emerald-500/30',
          iconContainer: 'bg-emerald-500/15 border-emerald-500/30 text-emerald-300',
          actionButton:
            'bg-slate-800 hover:bg-slate-700 text-slate-200 border-slate-700 active:scale-[0.98]',
          progressBar: 'bg-emerald-500',
        };
      case 'error':
        return {
          card: 'bg-slate-900/95 text-slate-100 shadow-2xl shadow-black/50 backdrop-blur-xl border-rose-500/30',
          iconContainer: 'bg-rose-500/15 border-rose-500/30 text-rose-300',
          actionButton:
            'bg-slate-800 hover:bg-slate-700 text-slate-200 border-slate-700 active:scale-[0.98]',
          progressBar: 'bg-rose-500',
        };
      case 'warning':
        return {
          card: 'bg-slate-900/95 text-slate-100 shadow-2xl shadow-black/50 backdrop-blur-xl border-amber-500/30',
          iconContainer: 'bg-amber-500/15 border-amber-500/30 text-amber-300',
          actionButton:
            'bg-slate-800 hover:bg-slate-700 text-slate-200 border-slate-700 active:scale-[0.98]',
          progressBar: 'bg-amber-500',
        };
      case 'info':
        return {
          card: 'bg-slate-900/95 text-slate-100 shadow-2xl shadow-black/50 backdrop-blur-xl border-sky-500/30',
          iconContainer: 'bg-sky-500/15 border-sky-500/30 text-sky-300',
          actionButton:
            'bg-slate-800 hover:bg-slate-700 text-slate-200 border-slate-700 active:scale-[0.98]',
          progressBar: 'bg-sky-500',
        };
      case 'loading':
        return {
          card: 'bg-slate-900/95 text-slate-100 shadow-2xl shadow-black/50 backdrop-blur-xl border-violet-500/30',
          iconContainer: 'bg-violet-500/15 border-violet-500/30 text-violet-300',
          actionButton:
            'bg-slate-800 hover:bg-slate-700 text-slate-200 border-slate-700 active:scale-[0.98]',
          progressBar: 'bg-violet-500',
        };
      default:
        return {
          card: 'bg-slate-900/95 text-slate-100 shadow-2xl shadow-black/50 backdrop-blur-xl border-slate-800',
          iconContainer: 'bg-slate-800 border-slate-700 text-slate-300',
          actionButton:
            'bg-slate-800 hover:bg-slate-700 text-slate-200 border-slate-700 active:scale-[0.98]',
          progressBar: 'bg-slate-500',
        };
    }
  }

  // theme === 'light'
  switch (type) {
    case 'success':
      return {
        card: 'bg-white text-slate-900 shadow-[0_8px_30px_rgb(0,0,0,0.08),0_2px_8px_rgb(0,0,0,0.04)] backdrop-blur-md border-emerald-200',
        iconContainer: 'bg-emerald-50 border-emerald-200/90 text-emerald-600',
        actionButton:
          'bg-slate-900 hover:bg-slate-800 text-white border-slate-900 active:scale-[0.98]',
        progressBar: 'bg-emerald-500',
      };
    case 'error':
      return {
        card: 'bg-white text-slate-900 shadow-[0_8px_30px_rgb(0,0,0,0.08),0_2px_8px_rgb(0,0,0,0.04)] backdrop-blur-md border-rose-200',
        iconContainer: 'bg-rose-50 border-rose-200/90 text-rose-600',
        actionButton:
          'bg-slate-900 hover:bg-slate-800 text-white border-slate-900 active:scale-[0.98]',
        progressBar: 'bg-rose-500',
      };
    case 'warning':
      return {
        card: 'bg-white text-slate-900 shadow-[0_8px_30px_rgb(0,0,0,0.08),0_2px_8px_rgb(0,0,0,0.04)] backdrop-blur-md border-amber-200',
        iconContainer: 'bg-amber-50 border-amber-200/90 text-amber-600',
        actionButton:
          'bg-slate-900 hover:bg-slate-800 text-white border-slate-900 active:scale-[0.98]',
        progressBar: 'bg-amber-500',
      };
    case 'info':
      return {
        card: 'bg-white text-slate-900 shadow-[0_8px_30px_rgb(0,0,0,0.08),0_2px_8px_rgb(0,0,0,0.04)] backdrop-blur-md border-sky-200',
        iconContainer: 'bg-sky-50 border-sky-200/90 text-sky-600',
        actionButton:
          'bg-slate-900 hover:bg-slate-800 text-white border-slate-900 active:scale-[0.98]',
        progressBar: 'bg-sky-500',
      };
    case 'loading':
      return {
        card: 'bg-white text-slate-900 shadow-[0_8px_30px_rgb(0,0,0,0.08),0_2px_8px_rgb(0,0,0,0.04)] backdrop-blur-md border-violet-200',
        iconContainer: 'bg-violet-50 border-violet-200/90 text-violet-600',
        actionButton:
          'bg-slate-900 hover:bg-slate-800 text-white border-slate-900 active:scale-[0.98]',
        progressBar: 'bg-violet-500',
      };
    default:
      return {
        card: 'bg-white text-slate-900 shadow-[0_8px_30px_rgb(0,0,0,0.08),0_2px_8px_rgb(0,0,0,0.04)] backdrop-blur-md border-slate-200/90',
        iconContainer: 'bg-slate-50 border-slate-200 text-slate-600',
        actionButton:
          'bg-slate-900 hover:bg-slate-800 text-white border-slate-900 active:scale-[0.98]',
        progressBar: 'bg-slate-400',
      };
  }
}
