import { forwardRef, useEffect, useId, useRef } from 'react';
import { Check, Minus } from 'lucide-react';

import { cn } from '../../../../utils/ui/cn';

import type { CheckboxProps } from '../../../../types/ui/field/checkbox.types';

export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(
  (
    {
      id: customId,
      checked = false,
      indeterminate = false,
      onChange,
      label,
      description,
      error,
      disabled = false,
      size = 'md',
      variant = 'default',
      className,
      wrapperClassName,
      ...props
    },
    ref
  ) => {
    const generatedId = useId();
    const inputId = customId || generatedId;
    const innerRef = useRef<HTMLInputElement>(null);

    // Sync indeterminate property on the native input DOM element
    useEffect(() => {
      const element = (ref && 'current' in ref && ref.current) ? ref.current : innerRef.current;
      if (element) {
        element.indeterminate = indeterminate;
      }
    }, [indeterminate, ref]);

    const boxSizeClasses = {
      sm: 'w-4 h-4 rounded',
      md: 'w-5 h-5 rounded-md',
      lg: 'w-6 h-6 rounded-lg',
    }[size];

    const iconSizeClasses = {
      sm: 'w-3 h-3 stroke-[3]',
      md: 'w-3.5 h-3.5 stroke-[2.5]',
      lg: 'w-4 h-4 stroke-[2.5]',
    }[size];

    const isCard = variant === 'card';

    return (
      <label
        htmlFor={inputId}
        className={cn(
          'relative flex items-start gap-3 select-none transition-all cursor-pointer',
          isCard &&
            cn(
              'p-3.5 rounded-xl border bg-slate-50/60 hover:bg-slate-50 transition-colors',
              checked ? 'border-emerald-500 bg-emerald-50/30 ring-1 ring-emerald-500/20' : 'border-slate-200'
            ),
          disabled && 'opacity-60 cursor-not-allowed hover:bg-transparent',
          wrapperClassName
        )}
      >
        <div className="relative flex items-center pt-0.5">
          <input
            ref={ref || innerRef}
            id={inputId}
            type="checkbox"
            checked={checked}
            onChange={(e) => onChange?.(e.target.checked)}
            disabled={disabled}
            className="sr-only peer"
            {...props}
          />
          <div
            className={cn(
              'flex items-center justify-center border transition-all duration-150 shadow-2xs peer-focus-visible:ring-2 peer-focus-visible:ring-emerald-500/40 peer-focus-visible:ring-offset-1',
              boxSizeClasses,
              checked || indeterminate
                ? 'bg-emerald-600 border-emerald-600 text-white shadow-emerald-500/20'
                : 'bg-white border-slate-300 hover:border-slate-400',
              Boolean(error) && 'border-rose-400 bg-rose-50/50',
              disabled && 'bg-slate-100 border-slate-300 text-slate-400 cursor-not-allowed',
              className
            )}
          >
            {indeterminate ? (
              <Minus className={iconSizeClasses} />
            ) : checked ? (
              <Check className={iconSizeClasses} />
            ) : null}
          </div>
        </div>

        {(label || description) && (
          <div className="flex flex-col">
            {label && (
              <span
                className={cn(
                  'font-medium text-slate-800 transition-colors leading-snug',
                  size === 'sm' ? 'text-xs' : size === 'lg' ? 'text-base' : 'text-sm',
                  disabled && 'text-slate-400'
                )}
              >
                {label}
              </span>
            )}
            {description && (
              <span
                className={cn(
                  'text-slate-500 text-xs mt-0.5 leading-normal',
                  disabled && 'text-slate-400'
                )}
              >
                {description}
              </span>
            )}
            {error && <span className="text-xs text-rose-500 font-medium mt-1">{error}</span>}
          </div>
        )}
      </label>
    );
  }
);

Checkbox.displayName = 'Checkbox';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { CheckboxProps } from '../../../../types/ui/field/checkbox.types';
