import { cn } from '../../../utils/ui/cn';

import { STACK_LAYER_CLASSES } from '../../../types/ui/layout.types';
import type { LayoutHeaderProps } from '../../../types/ui/layout.types';

export function LayoutHeader({
  height = 'h-14',
  sticky = true,
  bordered = true,
  layer = 'header',
  className = '',
  children,
}: LayoutHeaderProps) {
  const layerClass = STACK_LAYER_CLASSES[layer] || 'z-20';

  return (
    <header
      className={cn(
        'w-full shrink-0 flex items-center transition-colors',
        height,
        sticky ? 'sticky top-0' : 'relative',
        bordered && 'border-b border-slate-200 dark:border-slate-800',
        'bg-white/95 dark:bg-slate-900/95 backdrop-blur-xs',
        layerClass,
        className
      )}
    >
      {children}
    </header>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { LayoutHeaderProps } from '../../../types/ui/layout.types';
