import type { BadgeVariant, StatusCodeBadgeProps } from '../../../types/ui/badge.types';
import { Badge } from './index';

export function StatusCodeBadge({
  statusCode,
  className = '',
}: StatusCodeBadgeProps) {
  const variant: BadgeVariant =
    statusCode >= 200 && statusCode < 300
      ? 'success'
      : statusCode >= 300 && statusCode < 400
      ? 'info'
      : statusCode >= 400 && statusCode < 500
      ? 'warning'
      : statusCode >= 500
      ? 'danger'
      : 'default';

  return (
    <Badge variant={variant} size="xs" className={`font-mono font-semibold ${className}`}>
      {statusCode}
    </Badge>
  );
}
