import type { ReactNode } from 'react';
import { Check, Code2, Copy, FolderTree, Maximize2, Wand2 } from 'lucide-react';

import { Badge } from '../badge';
import { Button } from '../button';
import { Tabs } from '../tabs';

import { cn } from '../../../utils/ui/cn';

import type {
  CodeEditorLanguage,
  CodeEditorTheme,
  CodeEditorToolbarProps,
  CodeEditorViewMode,
} from '../../../types/ui/code-editor.types';
import type { TabItem, TabVariant } from '../../../types/ui/tabs.types';

export function CodeEditorToolbar({
  theme = 'dark',
  title,
  language = 'json',
  isValidJson = true,
  layout = 'auto',
  tabs,
  activeTab,
  onChangeTab,
  tabsVariant,
  tabsPosition = 'left',
  tabsActions,
  statusPosition = 'left',
  statusBadge,
  actionsPosition = 'right',
  viewMode = 'code',
  onViewModeChange,
  showViewToggle = true,
  isTreeSupported = false,
  showFormatButton = true,
  onFormat,
  readOnly = false,
  showCopyButton = true,
  copied = false,
  onCopy,
  showFullScreenButton = false,
  onFullScreen,
  extraActions,
  topRowLeft,
  topRowRight,
  bottomRowLeft,
  bottomRowRight,
  leftContent,
  centerContent,
  rightContent,
  className = '',
  children,
}: CodeEditorToolbarProps) {
  const isDark = theme === 'dark';
  const hasTabs = Boolean(tabs && tabs.length > 0);
  const hasCodeActions = Boolean(
    (showViewToggle && language === 'json') ||
      (!readOnly && showFormatButton && language === 'json') ||
      showCopyButton ||
      showFullScreenButton ||
      extraActions
  );

  // If custom children are provided, render as a customized wrapper
  if (children) {
    return (
      <div
        className={cn(
          'w-full flex flex-col border-b select-none transition-colors shrink-0',
          isDark
            ? 'bg-slate-900 border-slate-800 text-white'
            : 'bg-slate-100/95 border-slate-200 text-slate-800',
          className
        )}
      >
        {children}
      </div>
    );
  }

  // Determine if we should render 2-tier stacked or 1-tier single layout
  const isStacked =
    layout === 'stacked' ||
    (layout === 'auto' && hasTabs && hasCodeActions);

  // Reusable sub-elements
  const tabsElement = hasTabs ? (
    <CodeEditorToolbarTabs
      tabs={tabs!}
      activeTab={activeTab}
      onChangeTab={onChangeTab}
      tabsVariant={tabsVariant}
      theme={theme}
    />
  ) : null;

  const statusElement = statusPosition !== 'hidden' ? (
    <CodeEditorToolbarStatus
      title={title}
      language={language}
      isValidJson={isValidJson}
      statusBadge={statusBadge}
    />
  ) : null;

  const actionsElement = (
    <CodeEditorToolbarActions
      theme={theme}
      language={language}
      isValidJson={isValidJson}
      viewMode={viewMode}
      onViewModeChange={onViewModeChange}
      showViewToggle={showViewToggle}
      isTreeSupported={isTreeSupported}
      showFormatButton={showFormatButton}
      onFormat={onFormat}
      readOnly={readOnly}
      showCopyButton={showCopyButton}
      copied={copied}
      onCopy={onCopy}
      showFullScreenButton={showFullScreenButton}
      onFullScreen={onFullScreen}
      extraActions={extraActions}
    />
  );

  // ==========================================================================
  // STACKED (2-TIER) LAYOUT: Clean separation between Navigation & Code Actions
  // ==========================================================================
  if (isStacked) {
    return (
      <div className={cn('w-full flex flex-col shrink-0 select-none transition-colors', className)}>
        {/* Tier 1: Section / Document Tabs & Top-level View Switcher */}
        <div
          className={cn(
            'w-full flex items-center justify-between gap-2 px-3 py-1.5 border-b transition-colors',
            isDark
              ? 'bg-slate-900 border-slate-800 text-white'
              : 'bg-slate-100 border-slate-200 text-slate-800'
          )}
        >
          {topRowLeft ? (
            topRowLeft
          ) : (
            <div
              className={cn(
                'flex items-center gap-2 min-w-0 overflow-x-auto no-scrollbar scroll-smooth py-0.5',
                tabsPosition === 'center' && 'mx-auto justify-center',
                tabsPosition === 'right' && 'ml-auto justify-end'
              )}
            >
              {tabsPosition === 'left' && tabsElement}
              {tabsPosition === 'center' && tabsElement}
            </div>
          )}

          {topRowRight ? (
            topRowRight
          ) : (
            <div className="flex items-center gap-2 shrink-0 ml-auto">
              {tabsPosition === 'right' && tabsElement}
              {tabsActions}
            </div>
          )}
        </div>

        {/* Tier 2: Code Editor Controls (Status / Language & Action Buttons) */}
        {hasCodeActions && (
          <div
            className={cn(
              'w-full flex items-center justify-between gap-2 px-3 py-1 border-b transition-colors text-xs',
              isDark
                ? 'bg-slate-950/80 border-slate-800/80 text-slate-300'
                : 'bg-slate-50/90 border-slate-200/80 text-slate-700'
            )}
          >
            {bottomRowLeft ? (
              bottomRowLeft
            ) : actionsPosition === 'left' ? (
              <div className="flex items-center gap-1.5 shrink-0">{actionsElement}</div>
            ) : (
              <div className="flex items-center gap-2 min-w-0 shrink-0">
                {statusPosition === 'left' && statusElement}
              </div>
            )}

            {bottomRowRight ? (
              bottomRowRight
            ) : actionsPosition === 'right' ? (
              <div className="flex items-center gap-1.5 shrink-0 ml-auto">{actionsElement}</div>
            ) : (
              <div className="flex items-center gap-2 min-w-0 shrink-0 ml-auto">
                {statusPosition === 'right' && statusElement}
              </div>
            )}
          </div>
        )}
      </div>
    );
  }

  // ==========================================================================
  // SINGLE (1-TIER) LAYOUT: Compact bar for Standalone Editors or Tab-only Views
  // ==========================================================================
  return (
    <div
      className={cn(
        'w-full flex flex-wrap sm:flex-nowrap items-center justify-between gap-2 px-3 py-2 border-b select-none transition-colors shrink-0',
        isDark
          ? 'bg-slate-900 border-slate-800 text-white'
          : 'bg-slate-100/95 border-slate-200 text-slate-800',
        className
      )}
    >
      {/* Left Slot */}
      <div className="flex items-center gap-2 min-w-0 flex-shrink-0">
        {leftContent ? (
          leftContent
        ) : hasTabs ? (
          <div className="flex items-center gap-2 flex-wrap sm:flex-nowrap overflow-x-auto no-scrollbar">
            {tabsPosition === 'left' && tabsElement}
            {tabsPosition === 'left' && statusPosition === 'left' && statusElement}
          </div>
        ) : (
          statusPosition === 'left' && statusElement
        )}
      </div>

      {/* Center Slot */}
      {centerContent && (
        <div className="flex items-center justify-center flex-1 min-w-0">{centerContent}</div>
      )}

      {/* Right Slot */}
      <div className="flex items-center gap-1.5 flex-wrap sm:flex-nowrap justify-end ml-auto shrink-0">
        {rightContent ? (
          rightContent
        ) : (
          <>
            {tabsPosition === 'right' && tabsElement}
            {statusPosition === 'right' && statusElement}
            {tabsActions}
            {hasCodeActions && actionsElement}
          </>
        )}
      </div>
    </div>
  );
}

// ============================================================================
// SUB-COMPONENTS
// ============================================================================

export function CodeEditorToolbarRow({
  children,
  className = '',
  theme = 'dark',
  density = 'normal',
}: CodeEditorToolbarRowProps) {
  const isDark = theme === 'dark';
  return (
    <div
      className={cn(
        'w-full flex items-center justify-between gap-2 px-3 border-b transition-colors shrink-0',
        density === 'compact' ? 'py-1 text-xs' : 'py-1.5',
        isDark
          ? 'bg-slate-900 border-slate-800 text-white'
          : 'bg-slate-100 border-slate-200 text-slate-800',
        className
      )}
    >
      {children}
    </div>
  );
}

export function CodeEditorToolbarGroup({
  children,
  className = '',
  align = 'left',
}: CodeEditorToolbarGroupProps) {
  return (
    <div
      className={cn(
        'flex items-center gap-1.5 shrink-0',
        align === 'right' && 'ml-auto justify-end',
        align === 'center' && 'mx-auto justify-center',
        className
      )}
    >
      {children}
    </div>
  );
}

export function CodeEditorToolbarTabs({
  tabs,
  activeTab,
  onChangeTab,
  tabsVariant = 'pills',
  theme = 'dark',
  className = '',
}: CodeEditorToolbarTabsProps) {
  if (!tabs || tabs.length === 0) return null;
  return (
    <div className={cn('flex items-center overflow-x-auto no-scrollbar shrink-0', className)}>
      <Tabs
        items={tabs}
        value={activeTab}
        onChange={onChangeTab}
        variant={tabsVariant}
        size="sm"
        theme={theme}
      />
    </div>
  );
}

export function CodeEditorToolbarStatus({
  title,
  language = 'json',
  isValidJson = true,
  statusBadge,
  className = '',
}: CodeEditorToolbarStatusProps) {
  return (
    <div className={cn('flex items-center gap-2 min-w-0 shrink-0 font-mono text-xs', className)}>
      {title ? (
        <span className="text-xs font-semibold truncate max-w-[140px] sm:max-w-xs">{title}</span>
      ) : (
        <span className="text-xs font-bold uppercase tracking-wider opacity-80">{language}</span>
      )}

      {statusBadge ? (
        statusBadge
      ) : language === 'json' && isValidJson !== undefined ? (
        <Badge
          variant={isValidJson ? 'success' : 'danger'}
          size="xs"
          className="font-mono text-[10px] shrink-0"
        >
          {isValidJson ? 'Valid JSON' : 'Syntax Error'}
        </Badge>
      ) : null}
    </div>
  );
}

export function CodeEditorToolbarViewToggle({
  viewMode = 'code',
  onViewModeChange,
  isTreeSupported = false,
  theme = 'dark',
  className = '',
}: CodeEditorToolbarViewToggleProps) {
  const isDark = theme === 'dark';

  return (
    <div
      className={cn(
        'flex items-center p-0.5 rounded-lg text-xs font-medium border transition-colors shrink-0',
        isDark ? 'bg-slate-800/80 border-slate-700/60' : 'bg-slate-200/80 border-slate-300/80',
        className
      )}
    >
      <button
        type="button"
        onClick={() => onViewModeChange?.('code')}
        className={cn(
          'flex items-center gap-1 px-2 py-0.5 sm:px-2.5 sm:py-1 rounded-md transition-colors cursor-pointer text-xs',
          viewMode === 'code'
            ? isDark
              ? 'bg-slate-700 text-white shadow-2xs font-semibold'
              : 'bg-white text-slate-900 shadow-2xs font-semibold'
            : isDark
            ? 'text-slate-400 hover:text-white'
            : 'text-slate-600 hover:text-slate-900'
        )}
        title="Raw code view"
      >
        <Code2 className="w-3.5 h-3.5" />
        <span className="hidden xs:inline sm:inline">Code</span>
      </button>

      <button
        type="button"
        disabled={!isTreeSupported}
        onClick={() => isTreeSupported && onViewModeChange?.('tree')}
        className={cn(
          'flex items-center gap-1 px-2 py-0.5 sm:px-2.5 sm:py-1 rounded-md transition-colors text-xs',
          !isTreeSupported
            ? 'opacity-40 cursor-not-allowed text-slate-400'
            : viewMode === 'tree'
            ? isDark
              ? 'bg-slate-700 text-white shadow-2xs font-semibold cursor-pointer'
              : 'bg-white text-emerald-800 shadow-2xs font-semibold cursor-pointer'
            : isDark
            ? 'text-slate-400 hover:text-white cursor-pointer'
            : 'text-slate-600 hover:text-slate-900 cursor-pointer'
        )}
        title={
          !isTreeSupported
            ? 'Tree view is only available for valid JSON'
            : 'Interactive tree view'
        }
      >
        <FolderTree className="w-3.5 h-3.5" />
        <span className="hidden xs:inline sm:inline">Tree</span>
      </button>
    </div>
  );
}

export function CodeEditorToolbarActions({
  theme = 'dark',
  language = 'json',
  isValidJson = true,
  viewMode = 'code',
  onViewModeChange,
  showViewToggle = true,
  isTreeSupported = false,
  showFormatButton = true,
  onFormat,
  readOnly = false,
  showCopyButton = true,
  copied = false,
  onCopy,
  showFullScreenButton = false,
  onFullScreen,
  extraActions,
  className = '',
}: CodeEditorToolbarActionsProps) {
  const isDark = theme === 'dark';
  const buttonThemeClass = getToolbarButtonClass(isDark);

  return (
    <div className={cn('flex items-center gap-1.5 shrink-0', className)}>
      {/* View Mode Toggle: Code vs Tree (JSON only) */}
      {showViewToggle && language === 'json' && (
        <CodeEditorToolbarViewToggle
          viewMode={viewMode}
          onViewModeChange={onViewModeChange}
          isTreeSupported={isTreeSupported}
          theme={theme}
        />
      )}

      {/* Format Button */}
      {!readOnly && showFormatButton && language === 'json' && (
        <Button
          type="button"
          variant="outline"
          size="xs"
          disabled={!isValidJson}
          onClick={onFormat}
          leftIcon={<Wand2 className="w-3 h-3 text-emerald-500" />}
          className={cn(buttonThemeClass, 'shrink-0')}
          title="Format JSON (Prettify)"
        >
          <span className="hidden sm:inline">Format</span>
        </Button>
      )}

      {/* Copy Button */}
      {showCopyButton && (
        <Button
          type="button"
          variant="outline"
          size="xs"
          onClick={onCopy}
          leftIcon={
            copied ? <Check className="w-3 h-3 text-emerald-500" /> : <Copy className="w-3 h-3" />
          }
          className={cn(buttonThemeClass, 'shrink-0')}
          title="Copy code to clipboard"
        >
          <span className="hidden sm:inline">{copied ? 'Copied' : 'Copy'}</span>
        </Button>
      )}

      {/* Fullscreen Button */}
      {showFullScreenButton && (
        <Button
          type="button"
          variant="outline"
          size="xs"
          onClick={onFullScreen}
          leftIcon={<Maximize2 className="w-3 h-3 text-emerald-500" />}
          className={cn(buttonThemeClass, 'shrink-0')}
          title="Fullscreen mode"
        >
          <span className="hidden sm:inline">Fullscreen</span>
        </Button>
      )}

      {/* Custom Extra Actions */}
      {extraActions}
    </div>
  );
}

// Attach sub-components to CodeEditorToolbar for compound usage
CodeEditorToolbar.Row = CodeEditorToolbarRow;
CodeEditorToolbar.Group = CodeEditorToolbarGroup;
CodeEditorToolbar.Tabs = CodeEditorToolbarTabs;
CodeEditorToolbar.Status = CodeEditorToolbarStatus;
CodeEditorToolbar.ViewToggle = CodeEditorToolbarViewToggle;
CodeEditorToolbar.Actions = CodeEditorToolbarActions;

// ============================================================================
// HELPERS
// ============================================================================

export function getToolbarButtonClass(isDark: boolean): string {
  return isDark
    ? 'bg-slate-800 border-slate-700 text-slate-200 hover:bg-slate-700 hover:text-white'
    : 'bg-white border-slate-300 text-slate-700 hover:bg-slate-50';
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================

export interface CodeEditorToolbarRowProps {
  children: ReactNode;
  className?: string;
  theme?: CodeEditorTheme;
  density?: 'normal' | 'compact';
}

export interface CodeEditorToolbarGroupProps {
  children: ReactNode;
  className?: string;
  align?: 'left' | 'center' | 'right';
}

export interface CodeEditorToolbarTabsProps {
  tabs: TabItem[];
  activeTab?: string;
  onChangeTab?: (tabId: string) => void;
  tabsVariant?: TabVariant;
  theme?: CodeEditorTheme;
  className?: string;
}

export interface CodeEditorToolbarStatusProps {
  title?: ReactNode;
  language?: CodeEditorLanguage;
  isValidJson?: boolean;
  statusBadge?: ReactNode;
  className?: string;
}

export interface CodeEditorToolbarViewToggleProps {
  viewMode?: CodeEditorViewMode;
  onViewModeChange?: (mode: CodeEditorViewMode) => void;
  isTreeSupported?: boolean;
  theme?: CodeEditorTheme;
  className?: string;
}

export interface CodeEditorToolbarActionsProps {
  theme?: CodeEditorTheme;
  language?: CodeEditorLanguage;
  isValidJson?: boolean;
  viewMode?: CodeEditorViewMode;
  onViewModeChange?: (mode: CodeEditorViewMode) => void;
  showViewToggle?: boolean;
  isTreeSupported?: boolean;
  showFormatButton?: boolean;
  onFormat?: () => void;
  readOnly?: boolean;
  showCopyButton?: boolean;
  copied?: boolean;
  onCopy?: () => void;
  showFullScreenButton?: boolean;
  onFullScreen?: () => void;
  extraActions?: ReactNode;
  className?: string;
}
