import type { ReactNode } from 'react';
import { X } from 'lucide-react';

export function ModalHeader({
  children,
  onClose,
  className = '',
}: {
  children?: ReactNode;
  onClose?: () => void;
  className?: string;
}) {
  return (
    <div className={`flex items-center justify-between px-6 py-4 border-b border-slate-100 bg-slate-50/50 shrink-0 ${className}`}>
      <div className="min-w-0 flex-1">{children}</div>
      {onClose && (
        <button
          type="button"
          onClick={onClose}
          className="text-slate-400 hover:text-slate-700 p-1.5 rounded-lg hover:bg-slate-100 transition-colors cursor-pointer shrink-0 ml-3"
          aria-label="Tutup modal"
        >
          <X className="w-4 h-4" />
        </button>
      )}
    </div>
  );
}
