import type { CSSProperties } from 'react';

import { cn } from '../../../utils/ui/cn';

import { STACK_LAYER_CLASSES } from '../../../types/ui/layout.types';
import type { StackLayerProps } from '../../../types/ui/layout.types';

export function StackLayer({
  layer = 'base',
  zIndex,
  fixed = false,
  absolute = false,
  fullScreen = false,
  className = '',
  children,
}: StackLayerProps) {
  const layerClass = STACK_LAYER_CLASSES[layer] || 'z-0';

  const style: CSSProperties | undefined =
    zIndex !== undefined ? { zIndex } : undefined;

  return (
    <div
      style={style}
      className={cn(
        layerClass,
        fullScreen
          ? 'fixed inset-0 pointer-events-none'
          : fixed
          ? 'fixed'
          : absolute
          ? 'absolute'
          : 'relative',
        className
      )}
    >
      {children}
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { StackLayerProps } from '../../../types/ui/layout.types';
