/**
 * Format latensi dalam ms dengan satuan yang mudah dibaca
 */
export function formatLatency(ms?: number): string {
  if (ms === undefined || ms === null) return '-';
  if (ms < 1000) return `${Math.round(ms)}ms`;
  return `${(ms / 1000).toFixed(2)}s`;
}

/**
 * Format status code HTTP dengan label standar
 */
export function formatStatusCode(statusCode?: number): {
  code: number | string;
  category: 'success' | 'redirect' | 'client_error' | 'server_error' | 'unknown';
} {
  if (!statusCode) return { code: '-', category: 'unknown' };
  if (statusCode >= 200 && statusCode < 300) return { code: statusCode, category: 'success' };
  if (statusCode >= 300 && statusCode < 400) return { code: statusCode, category: 'redirect' };
  if (statusCode >= 400 && statusCode < 500) return { code: statusCode, category: 'client_error' };
  if (statusCode >= 500) return { code: statusCode, category: 'server_error' };
  return { code: statusCode, category: 'unknown' };
}

/**
 * Memotong teks panjang dengan akhiran ellipsis (...)
 */
export function truncateText(text: string, maxLength: number = 50): string {
  if (!text) return '';
  if (text.length <= maxLength) return text;
  return `${text.slice(0, maxLength)}...`;
}
