import { useEffect } from 'react';

import { cn } from '../../../utils/ui/cn';

import { STACK_LAYER_CLASSES } from '../../../types/ui/layout.types';
import type { LayoutBackdropProps } from '../../../types/ui/layout.types';

export function LayoutBackdrop({
  visible = false,
  onClick,
  blur = true,
  scope = 'full',
  layer = 'backdrop',
  className = '',
  children,
}: LayoutBackdropProps) {
  // Lock body scroll when full backdrop is visible
  useEffect(() => {
    if (!visible || scope !== 'full') return;

    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    return () => {
      document.body.style.overflow = originalOverflow;
    };
  }, [visible, scope]);

  if (!visible) return null;

  const layerClass = STACK_LAYER_CLASSES[layer] || 'z-40';

  return (
    <div
      role="presentation"
      aria-hidden="true"
      onClick={onClick}
      className={cn(
        scope === 'full' ? 'fixed inset-0' : 'absolute inset-0',
        'bg-slate-950/50 transition-all duration-200 select-none animate-in fade-in',
        blur && 'backdrop-blur-xs',
        layerClass,
        className
      )}
    >
      {children}
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { LayoutBackdropProps } from '../../../types/ui/layout.types';
