import { forwardRef, useId } from 'react';
import { X } from 'lucide-react';

import { FieldWrapper } from '../field-wrapper';

import { cn } from '../../../../utils/ui/cn';

import type { TextAreaProps } from '../../../../types/ui/field/textArea.types';

export const TextArea = forwardRef<HTMLTextAreaElement, TextAreaProps>(
  (
    {
      id: customId,
      name,
      value,
      defaultValue,
      onChange,
      placeholder,
      rows = 4,
      maxLength,
      showCount = false,
      disabled,
      readOnly,
      required,
      optional,
      label,
      error,
      helperText,
      hint,
      size = 'md',
      layout = 'vertical',
      clearable,
      onClear,
      wrapperClassName,
      className,
      ...props
    },
    ref
  ) => {
    const generatedId = useId();
    const textareaId = customId || generatedId;

    const currentLength = typeof value === 'string' ? value.length : typeof defaultValue === 'string' ? defaultValue.length : 0;
    const hasValue = currentLength > 0;

    const sizeClasses = {
      sm: 'p-2 text-xs',
      md: 'p-3 text-sm',
      lg: 'p-4 text-base',
    }[size];

    const textareaNode = (
      <div className="relative w-full">
        <textarea
          ref={ref}
          id={textareaId}
          name={name}
          value={value}
          defaultValue={defaultValue}
          onChange={onChange}
          rows={rows}
          maxLength={maxLength}
          placeholder={placeholder}
          disabled={disabled}
          readOnly={readOnly}
          required={required}
          className={cn(
            'w-full transition-colors text-slate-800 placeholder-slate-400 rounded-lg focus:outline-none resize-y',
            sizeClasses,
            error
              ? 'bg-rose-50/20 border border-rose-300 focus:border-rose-500 focus:ring-1 focus:ring-rose-500 text-rose-900'
              : 'bg-white hover:border-slate-400 focus:border-emerald-600 focus:ring-1 focus:ring-emerald-600 border border-slate-300',
            disabled && 'opacity-60 bg-slate-50/80 cursor-not-allowed border-slate-200',
            className
          )}
          {...props}
        />

        <div className="flex items-center justify-between mt-1 px-1">
          {clearable && hasValue && onClear && !disabled && !readOnly ? (
            <button
              type="button"
              onClick={onClear}
              className="inline-flex items-center gap-1 text-[11px] text-slate-400 hover:text-slate-600 transition-colors cursor-pointer"
            >
              <X className="w-3 h-3" />
              <span>Bersihkan</span>
            </button>
          ) : (
            <span />
          )}

          {showCount && (
            <span className="text-[11px] font-mono text-slate-400 select-none ml-auto">
              {currentLength}
              {maxLength ? ` / ${maxLength}` : ' karakter'}
            </span>
          )}
        </div>
      </div>
    );

    if (label || error || helperText || hint) {
      return (
        <FieldWrapper
          htmlFor={textareaId}
          label={label}
          error={error}
          helperText={helperText}
          hint={hint}
          required={required}
          optional={optional}
          disabled={disabled}
          size={size}
          layout={layout}
          className={wrapperClassName}
        >
          {textareaNode}
        </FieldWrapper>
      );
    }

    return textareaNode;
  }
);

TextArea.displayName = 'TextArea';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { TextAreaProps } from '../../../../types/ui/field/textArea.types';
