import { forwardRef, useEffect, useId, useMemo, useRef, useState } from 'react';
import { Check, ChevronDown, Loader2, X } from 'lucide-react';

import { FieldWrapper } from '../field-wrapper';

import { cn } from '../../../../utils/ui/cn';

import type { AutocompleteOption, AutocompleteProps } from '../../../../types/ui/field/autocomplete.types';

export const Autocomplete = forwardRef<HTMLInputElement, AutocompleteProps>(
  (
    {
      options,
      value = '',
      onChange,
      placeholder = 'Ketik untuk mencari...',
      label,
      error,
      helperText,
      hint,
      required,
      optional,
      disabled,
      size = 'md',
      layout = 'vertical',
      clearable = true,
      loading = false,
      emptyText = 'Tidak ada pilihan yang cocok',
      leftIcon,
      filterFn,
      renderOption,
      className,
      wrapperClassName,
    },
    ref
  ) => {
    const generatedId = useId();
    const containerRef = useRef<HTMLDivElement>(null);
    const listRef = useRef<HTMLUListElement>(null);

    const [isOpen, setIsOpen] = useState(false);
    const [query, setQuery] = useState('');
    const [highlightedIndex, setHighlightedIndex] = useState(-1);

    // Normalize options into AutocompleteOption[]
    const normalizedOptions: AutocompleteOption[] = useMemo(() => {
      return options.map((opt) => (typeof opt === 'string' ? { label: opt, value: opt } : opt));
    }, [options]);

    // Find currently selected option based on value prop
    const selectedOption = useMemo(() => {
      return normalizedOptions.find((opt) => opt.value === value);
    }, [normalizedOptions, value]);

    // Keep input query synced with selected option or initial value
    useEffect(() => {
      if (selectedOption) {
        setQuery(selectedOption.label);
      } else if (!value) {
        setQuery('');
      }
    }, [selectedOption, value]);

    // Filter options based on query
    const filteredOptions = useMemo(() => {
      if (!query.trim()) return normalizedOptions;

      if (filterFn) {
        return normalizedOptions.filter((opt) => filterFn(opt, query));
      }

      const q = query.toLowerCase();
      return normalizedOptions.filter(
        (opt) => opt.label.toLowerCase().includes(q) || (opt.description && opt.description.toLowerCase().includes(q))
      );
    }, [normalizedOptions, query, filterFn]);

    // Close on click outside
    useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
        if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
          setIsOpen(false);
          // Revert to selected option's label if user typed but didn't select
          if (selectedOption) {
            setQuery(selectedOption.label);
          } else {
            setQuery('');
          }
        }
      };

      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [selectedOption]);

    const handleSelect = (option: AutocompleteOption) => {
      if (option.disabled) return;
      setQuery(option.label);
      setIsOpen(false);
      onChange?.(option.value, option);
    };

    const handleClear = () => {
      setQuery('');
      setIsOpen(false);
      onChange?.('');
    };

    const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
      if (disabled) return;

      if (!isOpen) {
        if (e.key === 'ArrowDown' || e.key === 'Enter') {
          setIsOpen(true);
          return;
        }
      }

      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault();
          setHighlightedIndex((prev) => (prev < filteredOptions.length - 1 ? prev + 1 : 0));
          break;
        case 'ArrowUp':
          e.preventDefault();
          setHighlightedIndex((prev) => (prev > 0 ? prev - 1 : filteredOptions.length - 1));
          break;
        case 'Enter':
          e.preventDefault();
          if (highlightedIndex >= 0 && highlightedIndex < filteredOptions.length) {
            handleSelect(filteredOptions[highlightedIndex]);
          }
          break;
        case 'Escape':
          setIsOpen(false);
          break;
      }
    };

    const sizeClasses = {
      sm: 'py-1.5 text-xs',
      md: 'py-2.5 text-sm',
      lg: 'py-3 text-base',
    }[size];

    const paddingClasses = {
      sm: cn(leftIcon ? 'pl-8' : 'pl-3', 'pr-14'),
      md: cn(leftIcon ? 'pl-9' : 'pl-3.5', 'pr-16'),
      lg: cn(leftIcon ? 'pl-11' : 'pl-4', 'pr-18'),
    }[size];

    const autocompleteNode = (
      <div ref={containerRef} className="relative w-full">
        <div className="relative flex items-center">
          {leftIcon && (
            <div className="absolute left-3 flex items-center pointer-events-none text-slate-400">
              <span className="w-4 h-4">{leftIcon}</span>
            </div>
          )}

          <input
            ref={ref}
            id={generatedId}
            type="text"
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              setIsOpen(true);
              setHighlightedIndex(0);
            }}
            onFocus={() => setIsOpen(true)}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            disabled={disabled}
            className={cn(
              'w-full transition-colors text-slate-800 placeholder-slate-400 rounded-lg focus:outline-none',
              sizeClasses,
              paddingClasses,
              error
                ? 'bg-rose-50/20 border border-rose-300 focus:border-rose-500 focus:ring-1 focus:ring-rose-500 text-rose-900'
                : 'bg-white hover:border-slate-400 focus:border-emerald-600 focus:ring-1 focus:ring-emerald-600 border border-slate-300',
              disabled && 'opacity-60 bg-slate-50/80 cursor-not-allowed border-slate-200',
              className
            )}
            autoComplete="off"
            role="combobox"
            aria-expanded={isOpen}
            aria-autocomplete="list"
          />

          <div className="absolute right-2.5 flex items-center gap-1">
            {loading && <Loader2 className="w-4 h-4 text-emerald-600 animate-spin" />}

            {clearable && query && !disabled && (
              <button
                type="button"
                onClick={handleClear}
                className="p-1 rounded-md text-slate-400 hover:text-slate-600 hover:bg-slate-200/60 transition-colors cursor-pointer"
                aria-label="Bersihkan input"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            )}

            <button
              type="button"
              onClick={() => !disabled && setIsOpen((prev) => !prev)}
              className="p-1 rounded-md text-slate-400 hover:text-slate-600 transition-transform duration-200 cursor-pointer"
              tabIndex={-1}
              aria-label="Toggle dropdown"
            >
              <ChevronDown className={cn('w-4 h-4 transition-transform duration-200', isOpen && 'rotate-180')} />
            </button>
          </div>
        </div>

        {isOpen && (
          <div className="absolute z-50 w-full mt-1.5 bg-white border border-slate-200 rounded-lg shadow-xl overflow-hidden animate-in fade-in zoom-in-95 duration-100 max-h-60 overflow-y-auto">
            {filteredOptions.length === 0 ? (
              <div className="px-4 py-3 text-xs text-slate-500 text-center select-none">{emptyText}</div>
            ) : (
              <ul ref={listRef} role="listbox" className="p-1">
                {filteredOptions.map((option, idx) => {
                  const isSelected = option.value === value;
                  const isHighlighted = idx === highlightedIndex;

                  return (
                    <li
                      key={option.value}
                      role="option"
                      aria-selected={isSelected}
                      onClick={() => handleSelect(option)}
                      onMouseEnter={() => setHighlightedIndex(idx)}
                      className={cn(
                        'flex items-center justify-between px-3 py-2 text-xs md:text-sm rounded-lg cursor-pointer transition-colors select-none',
                        isHighlighted ? 'bg-slate-100 text-slate-900' : 'text-slate-700',
                        isSelected && 'bg-emerald-50 text-emerald-900 font-medium',
                        option.disabled && 'opacity-40 cursor-not-allowed hover:bg-transparent'
                      )}
                    >
                      {renderOption ? (
                        renderOption(option, isSelected)
                      ) : (
                        <div className="flex flex-col">
                          <span className="flex items-center gap-2">
                            {option.icon && <span className="shrink-0">{option.icon}</span>}
                            <span>{option.label}</span>
                          </span>
                          {option.description && (
                            <span className="text-[11px] text-slate-400 font-normal">{option.description}</span>
                          )}
                        </div>
                      )}

                      {isSelected && <Check className="w-4 h-4 text-emerald-600 shrink-0 ml-2" />}
                    </li>
                  );
                })}
              </ul>
            )}
          </div>
        )}
      </div>
    );

    if (label || error || helperText || hint) {
      return (
        <FieldWrapper
          htmlFor={generatedId}
          label={label}
          error={error}
          helperText={helperText}
          hint={hint}
          required={required}
          optional={optional}
          disabled={disabled}
          size={size}
          layout={layout}
          className={wrapperClassName}
        >
          {autocompleteNode}
        </FieldWrapper>
      );
    }

    return autocompleteNode;
  }
);

Autocomplete.displayName = 'Autocomplete';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { AutocompleteOption, AutocompleteProps } from '../../../../types/ui/field/autocomplete.types';
