import { useCardContext } from './CardContext';

import { cn } from '../../../utils/ui/cn';

import type { CardFooterProps } from '../../../types/ui/card.types';

export function CardFooter({ children, className = '', ...props }: CardFooterProps) {
  const cardCtx = useCardContext();
  const isCollapsible = cardCtx?.collapsible ?? false;
  const isCollapsed = cardCtx?.isCollapsed ?? false;

  if (isCollapsible && isCollapsed) {
    return null;
  }

  return (
    <div
      className={cn(
        'px-5 py-3.5 bg-slate-50/80 border-t border-slate-100 flex items-center justify-between gap-2 text-xs text-slate-600 transition-colors',
        className
      )}
      {...props}
    >
      {children}
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { CardFooterProps } from '../../../types/ui/card.types';
