import { useEffect, useMemo, useState } from 'react';
import { createPortal } from 'react-dom';

import { ToastItem } from './ToastItem';
import { toast, useToastStore } from './toastStore';

import { cn } from '../../../utils/ui/cn';

import type {
  ToastContainerProps,
  ToastPosition,
} from '../../../types/ui/toast.types';

export function ToastContainer({
  position = 'top-center',
  toasts: controlledToasts,
  toast: controlledSingleToast,
  onDismiss: controlledOnDismiss,
  theme = 'colored',
  expandOnHover = true,
  maxVisible = 5,
  showProgress = true,
  className = '',
  containerClassName = '',
}: ToastContainerProps) {
  const storeToasts = useToastStore();
  const [isHovered, setIsHovered] = useState(false);
  const [isMounted, setIsMounted] = useState(false);
  const [systemIsDark, setSystemIsDark] = useState(false);

  useEffect(() => {
    setIsMounted(true);
    if (typeof window === 'undefined') return;

    const checkDark = () => {
      const isHtmlDark = document.documentElement.classList.contains('dark');
      const isMediaDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      setSystemIsDark(isHtmlDark || isMediaDark);
    };

    checkDark();

    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    mq.addEventListener('change', checkDark);
    return () => mq.removeEventListener('change', checkDark);
  }, []);

  const resolvedTheme: 'colored' | 'light' | 'dark' =
    theme === 'system' ? (systemIsDark ? 'dark' : 'light') : theme;

  // Determine active toasts (controlled prop vs uncontrolled store)
  const activeToasts = useMemo(() => {
    if (controlledToasts !== undefined) {
      return controlledToasts;
    }
    if (controlledSingleToast !== undefined) {
      return controlledSingleToast ? [controlledSingleToast] : [];
    }
    return storeToasts;
  }, [controlledToasts, controlledSingleToast, storeToasts]);

  const handleDismiss = (id: string) => {
    if (controlledOnDismiss) {
      controlledOnDismiss(id);
    } else {
      toast.dismiss(id);
    }
  };

  if (!isMounted || activeToasts.length === 0) {
    return null;
  }

  // Reverse so newest toast is index 0 in the list
  const orderedToasts = [...activeToasts].reverse().slice(0, maxVisible);
  const positionClasses = getPositionClasses(position);
  const isExpanded = expandOnHover && isHovered;

  const content = (
    <div
      className={cn(
        'fixed z-[100] pointer-events-none p-4 w-full max-w-md flex flex-col',
        positionClasses.wrapper,
        containerClassName
      )}
      role="region"
      aria-live="polite"
      aria-label="Notifikasi sistem"
    >
      <div
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
        className={cn(
          'relative w-full flex flex-col pointer-events-auto transition-all duration-300',
          positionClasses.alignment,
          isExpanded ? 'space-y-2.5' : 'h-18',
          className
        )}
      >
        {orderedToasts.map((item, index) => (
          <ToastItem
            key={item.id || `toast-${index}`}
            toast={item}
            index={index}
            total={orderedToasts.length}
            isExpanded={isExpanded}
            position={position}
            onDismiss={handleDismiss}
            theme={resolvedTheme}
            showProgress={showProgress}
          />
        ))}
      </div>
    </div>
  );

  return typeof document !== 'undefined' ? createPortal(content, document.body) : null;
}

export const Toaster = ToastContainer;

// ============================================================================
// HELPERS
// ============================================================================

interface PositionClasses {
  wrapper: string;
  alignment: string;
}

function getPositionClasses(position: ToastPosition): PositionClasses {
  switch (position) {
    case 'top-left':
      return {
        wrapper: 'top-5 left-5 items-start',
        alignment: 'items-start',
      };
    case 'top-center':
      return {
        wrapper: 'top-5 left-1/2 -translate-x-1/2 items-center',
        alignment: 'items-center',
      };
    case 'top-right':
      return {
        wrapper: 'top-5 right-5 items-end',
        alignment: 'items-end',
      };
    case 'bottom-left':
      return {
        wrapper: 'bottom-5 left-5 items-start',
        alignment: 'items-start',
      };
    case 'bottom-center':
      return {
        wrapper: 'bottom-5 left-1/2 -translate-x-1/2 items-center',
        alignment: 'items-center',
      };
    case 'bottom-right':
      return {
        wrapper: 'bottom-5 right-5 items-end',
        alignment: 'items-end',
      };
    default:
      return {
        wrapper: 'top-5 left-1/2 -translate-x-1/2 items-center',
        alignment: 'items-center',
      };
  }
}
