import { forwardRef } from 'react';
import { AlertCircle, HelpCircle } from 'lucide-react';

import { cn } from '../../../../utils/ui/cn';

import type { FieldWrapperProps } from '../../../../types/ui/field/fieldWrapper.types';

export const FieldWrapper = forwardRef<HTMLDivElement, FieldWrapperProps>(
  (
    {
      label,
      error,
      helperText,
      hint,
      required,
      optional,
      disabled,
      size = 'md',
      layout = 'vertical',
      htmlFor,
      className,
      labelClassName,
      children,
      ...props
    },
    ref
  ) => {
    const isHorizontal = layout === 'horizontal';

    const labelSizeClasses = {
      sm: 'text-xs',
      md: 'text-sm',
      lg: 'text-base font-semibold',
    }[size];

    return (
      <div
        ref={ref}
        className={cn(
          'w-full',
          isHorizontal ? 'grid grid-cols-1 md:grid-cols-3 gap-2 md:gap-4 items-start' : 'space-y-1.5',
          disabled && 'opacity-60 cursor-not-allowed',
          className
        )}
        {...props}
      >
        {label ? (
          <div className={cn(isHorizontal && 'pt-2 md:text-right')}>
            <label
              htmlFor={htmlFor}
              className={cn(
                'inline-flex items-center gap-1 font-medium text-slate-700 select-none transition-colors',
                error ? 'text-rose-600' : '',
                labelSizeClasses,
                labelClassName
              )}
            >
              <span>{label}</span>
              {required && (
                <span className="text-rose-500 font-bold ml-0.5" aria-hidden="true">
                  *
                </span>
              )}
              {optional && (
                <span className="text-[11px] font-normal text-slate-400 ml-1">
                  (Opsional)
                </span>
              )}
              {hint && (
                <span
                  className="text-slate-400 hover:text-slate-600 cursor-help transition-colors"
                  title={typeof hint === 'string' ? hint : undefined}
                >
                  <HelpCircle className="w-3.5 h-3.5 inline ml-0.5" />
                </span>
              )}
            </label>
          </div>
        ) : null}

        <div className={cn('w-full', isHorizontal && (label ? 'md:col-span-2' : 'md:col-span-3'))}>
          {children}

          {error ? (
            <p className="mt-1.5 text-xs text-rose-500 font-medium flex items-center gap-1.5 animate-in fade-in slide-in-from-top-0.5 duration-150">
              <AlertCircle className="w-3.5 h-3.5 shrink-0" />
              <span>{error}</span>
            </p>
          ) : helperText ? (
            <p className="mt-1.5 text-xs text-slate-500">
              {helperText}
            </p>
          ) : null}
        </div>
      </div>
    );
  }
);

FieldWrapper.displayName = 'FieldWrapper';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { FieldWrapperProps, FieldSize, FieldLayout } from '../../../../types/ui/field/fieldWrapper.types';
