import type { KeyboardEvent, MouseEvent } from 'react';
import { ChevronDown } from 'lucide-react';

import { useCardContext } from './CardContext';

import { cn } from '../../../utils/ui/cn';

import type { CardHeaderProps } from '../../../types/ui/card.types';

export function CardHeader({
  children,
  className = '',
  title,
  description,
  icon,
  iconBgColor,
  badge,
  actionSlot,
  actions,
  collapsible: propCollapsible,
  showCollapseTrigger = true,
  onClick,
  onKeyDown,
  ...props
}: CardHeaderProps) {
  const cardCtx = useCardContext();
  const isCollapsible = propCollapsible ?? cardCtx?.collapsible ?? false;
  const isCollapsed = cardCtx?.isCollapsed ?? false;
  const toggleCollapse = cardCtx?.toggleCollapse ?? (() => {});

  const handleHeaderClick = (e: MouseEvent<HTMLDivElement>) => {
    if (onClick) {
      onClick(e);
    }
    if (isCollapsible && !e.defaultPrevented) {
      toggleCollapse();
    }
  };

  const handleHeaderKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (onKeyDown) {
      onKeyDown(e);
    }
    if (isCollapsible && (e.key === 'Enter' || e.key === ' ')) {
      e.preventDefault();
      toggleCollapse();
    }
  };

  const hasStructuredContent = Boolean(title || description || icon || badge || actionSlot || actions);

  return (
    <div
      role={isCollapsible ? 'button' : undefined}
      tabIndex={isCollapsible ? 0 : undefined}
      aria-expanded={isCollapsible ? !isCollapsed : undefined}
      onClick={isCollapsible ? handleHeaderClick : onClick}
      onKeyDown={isCollapsible ? handleHeaderKeyDown : onKeyDown}
      className={cn(
        'px-5 py-3.5 flex items-center justify-between gap-3 transition-all',
        isCollapsible && isCollapsed ? 'border-b-0' : 'border-b border-slate-200/70',
        isCollapsible && 'cursor-pointer select-none group',
        className
      )}
      {...props}
    >
      {hasStructuredContent ? (
        <>
          <div className="flex items-start gap-3 min-w-0">
            {icon && (
              <div
                className={cn(
                  'p-2 rounded-xl border shadow-2xs shrink-0 transition-transform group-hover:scale-105',
                  iconBgColor || 'bg-slate-50 text-slate-700 border-slate-200'
                )}
              >
                {icon}
              </div>
            )}
            <div className="min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                {typeof title === 'string' ? (
                  <h3 className="text-sm font-semibold text-slate-900 group-hover:text-blue-600 transition-colors">
                    {title}
                  </h3>
                ) : (
                  title
                )}
                {badge}
              </div>
              {description && (
                <p className="text-xs text-slate-500 mt-0.5 leading-relaxed">
                  {description}
                </p>
              )}
            </div>
          </div>

          <div className="flex items-center gap-2 shrink-0">
            {(actionSlot || actions) && (
              <div
                onClick={(e) => e.stopPropagation()}
                className="flex items-center gap-2"
              >
                {actionSlot || actions}
              </div>
            )}
            {isCollapsible && showCollapseTrigger && (
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  toggleCollapse();
                }}
                className="p-1.5 rounded-lg text-slate-400 group-hover:text-slate-700 hover:bg-slate-100 transition-all cursor-pointer focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                title={isCollapsed ? 'Expand' : 'Collapse'}
                aria-expanded={!isCollapsed}
              >
                <ChevronDown
                  className={cn(
                    'w-4 h-4 transition-transform duration-200',
                    !isCollapsed && 'rotate-180 text-blue-600'
                  )}
                />
              </button>
            )}
          </div>
        </>
      ) : (
        <>
          <div className="flex items-center justify-between gap-3 w-full">
            {children}
            {isCollapsible && showCollapseTrigger && (
              <button
                type="button"
                onClick={(e) => {
                  e.stopPropagation();
                  toggleCollapse();
                }}
                className="p-1.5 rounded-lg text-slate-400 group-hover:text-slate-700 hover:bg-slate-100 transition-all cursor-pointer focus:outline-none focus:ring-2 focus:ring-blue-500/20 shrink-0"
                title={isCollapsed ? 'Expand' : 'Collapse'}
                aria-expanded={!isCollapsed}
              >
                <ChevronDown
                  className={cn(
                    'w-4 h-4 transition-transform duration-200',
                    !isCollapsed && 'rotate-180 text-blue-600'
                  )}
                />
              </button>
            )}
          </div>
        </>
      )}
    </div>
  );
}

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { CardHeaderProps } from '../../../types/ui/card.types';
