import { useMemo, useRef, useState } from 'react';
import type { UIEvent } from 'react';
import { AlertCircle } from 'lucide-react';

import { CodeEditorToolbar } from './CodeEditorToolbar';
import { CodeGutter } from './CodeGutter';
import { JsonTreeViewer } from './JsonTreeViewer';

import { cn } from '../../../utils/ui/cn';

import type {
  CodeEditorProps,
  CodeEditorToolbarProps,
  CodeEditorViewMode,
} from '../../../types/ui/code-editor.types';

export function CodeEditor({
  value,
  onChange,
  language = 'json',
  readOnly = false,
  theme = 'dark',
  viewMode: controlledViewMode,
  onViewModeChange,
  showLineNumbers = true,
  showToolbar = true,
  showViewToggle = true,
  showFormatButton = true,
  showCopyButton = true,
  showFullScreenButton = false,
  onFullScreen,
  onFormat,
  tabs,
  activeTab,
  onChangeTab,
  tabsVariant,
  tabsPosition,
  tabsActions,
  toolbarLayout = 'auto',
  statusPosition,
  actionsPosition,
  customToolbar,
  toolbarProps: toolbarPropsOverride,
  height = '360px',
  maxHeight,
  className = '',
  editorClassName = '',
  placeholder = '',
  title,
  extraActions,
  searchTerm = '',
}: CodeEditorProps) {
  const isDark = theme === 'dark';
  const [internalViewMode, setInternalViewMode] = useState<CodeEditorViewMode>('code');
  const [copied, setCopied] = useState(false);

  const viewMode = controlledViewMode !== undefined ? controlledViewMode : internalViewMode;

  const setViewMode = (mode: CodeEditorViewMode) => {
    if (controlledViewMode === undefined) {
      setInternalViewMode(mode);
    }
    onViewModeChange?.(mode);
  };

  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const gutterRef = useRef<HTMLDivElement>(null);

  // Synchronize textarea scroll with line number gutter
  const handleScroll = (e: UIEvent<HTMLTextAreaElement>) => {
    if (gutterRef.current) {
      gutterRef.current.scrollTop = e.currentTarget.scrollTop;
    }
  };

  // Parse JSON validation status & parsed object
  const { isValidJson, parsedJson, parseError } = useMemo(() => {
    if (language !== 'json') {
      return { isValidJson: true, parsedJson: null, parseError: null };
    }
    if (!value || !value.trim()) {
      return { isValidJson: true, parsedJson: null, parseError: null };
    }
    try {
      const parsed = JSON.parse(value);
      return { isValidJson: true, parsedJson: parsed, parseError: null };
    } catch (err: any) {
      return {
        isValidJson: false,
        parsedJson: null,
        parseError: err.message || 'Format JSON tidak valid',
      };
    }
  }, [value, language]);

  // Line count
  const lineCount = useMemo(() => {
    return Math.max(1, (value || '').split('\n').length);
  }, [value]);

  const lineNumbers = useMemo(() => {
    return Array.from({ length: lineCount }, (_, i) => i + 1);
  }, [lineCount]);

  // Actions
  const handleFormat = () => {
    if (onFormat) {
      onFormat();
      return;
    }
    if (readOnly || !onChange || language !== 'json') return;
    try {
      const parsed = JSON.parse(value);
      onChange(JSON.stringify(parsed, null, 2));
    } catch {
      // Ignored if invalid
    }
  };

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(value);
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    } catch {
      // Ignored
    }
  };

  const handleTreeChange = (updated: unknown) => {
    if (readOnly || !onChange) return;
    try {
      onChange(JSON.stringify(updated, null, 2));
    } catch {
      // Ignored
    }
  };

  const isTreeSupported = language === 'json' && isValidJson && parsedJson !== null;

  const toolbarProps: CodeEditorToolbarProps = {
    theme,
    title,
    language,
    isValidJson,
    layout: toolbarLayout,
    tabs,
    activeTab,
    onChangeTab,
    tabsVariant,
    tabsPosition,
    tabsActions,
    statusPosition,
    actionsPosition,
    viewMode,
    onViewModeChange: setViewMode,
    showViewToggle,
    isTreeSupported,
    showFormatButton,
    onFormat: handleFormat,
    readOnly,
    showCopyButton,
    copied,
    onCopy: handleCopy,
    showFullScreenButton,
    onFullScreen,
    extraActions,
    ...toolbarPropsOverride,
  };

  return (
    <div
      className={cn(
        'w-full flex flex-col rounded-2xl border overflow-hidden shadow-2xs transition-colors',
        isDark ? 'border-slate-800 bg-slate-950' : 'border-slate-200/90 bg-white',
        className
      )}
    >
      {/* Top Header / Toolbar */}
      {showToolbar && (
        customToolbar ? (
          typeof customToolbar === 'function' ? (
            customToolbar(toolbarProps)
          ) : (
            customToolbar
          )
        ) : (
          <CodeEditorToolbar {...toolbarProps} />
        )
      )}

      {/* Editor Body */}
      <div
        style={{ height, maxHeight }}
        className={cn(
          'relative w-full flex overflow-hidden font-mono text-xs transition-colors',
          isDark ? 'bg-slate-950 text-slate-100' : 'bg-white text-slate-900',
          editorClassName
        )}
      >
        {viewMode === 'tree' && isTreeSupported ? (
          <div className="w-full h-full overflow-auto p-2">
            <JsonTreeViewer
              data={parsedJson}
              onChange={handleTreeChange}
              readOnly={readOnly}
              theme={theme}
              searchTerm={searchTerm}
            />
          </div>
        ) : (
          <div className="w-full h-full flex overflow-hidden">
            {/* Gutter Line Numbers */}
            {showLineNumbers && (
              <CodeGutter gutterRef={gutterRef} lineNumbers={lineNumbers} theme={theme} />
            )}

            {/* Textarea Area */}
            <div className="flex-1 relative h-full">
              <textarea
                ref={textareaRef}
                value={value}
                onChange={(e) => onChange?.(e.target.value)}
                readOnly={readOnly}
                placeholder={placeholder}
                onScroll={handleScroll}
                spellCheck={false}
                className={cn(
                  'w-full h-full p-3 font-mono text-xs leading-relaxed resize-none focus:outline-none focus:ring-0 border-0 overflow-auto whitespace-pre tab-[2] transition-colors',
                  isDark
                    ? 'text-slate-100 bg-transparent placeholder-slate-600'
                    : 'text-slate-900 bg-transparent placeholder-slate-400',
                  readOnly ? 'cursor-default' : 'cursor-text'
                )}
              />
            </div>
          </div>
        )}
      </div>

      {/* Footer Error Bar (if JSON invalid in code mode) */}
      {language === 'json' && !isValidJson && parseError && (
        <div
          className={cn(
            'px-3 py-1.5 border-t text-xs flex items-center gap-1.5 font-medium transition-colors',
            isDark
              ? 'bg-rose-950/60 border-rose-900 text-rose-300'
              : 'bg-rose-50 border-rose-200 text-rose-700'
          )}
        >
          <AlertCircle className="w-3.5 h-3.5 shrink-0 text-rose-500" />
          <span className="truncate">{parseError}</span>
        </div>
      )}
    </div>
  );
}

export const JsonEditor = CodeEditor;

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type {
  CodeEditorProps,
  CodeEditorTheme,
  CodeEditorViewMode,
  JsonEditorProps,
} from '../../../types/ui/code-editor.types';
