import { forwardRef, useId } from 'react';

import { cn } from '../../../../utils/ui/cn';

import type { SwitchProps } from '../../../../types/ui/field/switch.types';

export const Switch = forwardRef<HTMLButtonElement, SwitchProps>(
  (
    {
      checked = false,
      onChange,
      label,
      description,
      disabled = false,
      size = 'md',
      checkedIcon,
      uncheckedIcon,
      className,
      wrapperClassName,
    },
    ref
  ) => {
    const generatedId = useId();

    const trackSizeClasses = {
      sm: 'w-8 h-4.5 p-0.5',
      md: 'w-11 h-6 p-0.5',
      lg: 'w-14 h-7.5 p-1',
    }[size];

    const thumbSizeClasses = {
      sm: 'w-3.5 h-3.5',
      md: 'w-5 h-5',
      lg: 'w-5.5 h-5.5',
    }[size];

    const thumbTranslateClasses = {
      sm: checked ? 'translate-x-3.5' : 'translate-x-0',
      md: checked ? 'translate-x-5' : 'translate-x-0',
      lg: checked ? 'translate-x-6.5' : 'translate-x-0',
    }[size];

    return (
      <div
        className={cn(
          'flex items-start gap-3 select-none',
          disabled && 'opacity-60 cursor-not-allowed',
          wrapperClassName
        )}
      >
        <button
          ref={ref}
          id={generatedId}
          type="button"
          role="switch"
          aria-checked={checked}
          disabled={disabled}
          onClick={() => !disabled && onChange?.(!checked)}
          className={cn(
            'relative inline-flex shrink-0 rounded-full transition-colors duration-200 ease-in-out focus:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500/40 focus-visible:ring-offset-1 cursor-pointer',
            trackSizeClasses,
            checked ? 'bg-emerald-600' : 'bg-slate-300 hover:bg-slate-400/80',
            disabled && 'cursor-not-allowed hover:bg-slate-300',
            className
          )}
        >
          <span
            className={cn(
              'pointer-events-none inline-flex items-center justify-center rounded-full bg-white shadow-sm ring-0 transition duration-200 ease-in-out',
              thumbSizeClasses,
              thumbTranslateClasses
            )}
          >
            {checked ? checkedIcon : uncheckedIcon}
          </span>
        </button>

        {(label || description) && (
          <label htmlFor={generatedId} className="flex flex-col cursor-pointer">
            {label && (
              <span
                className={cn(
                  'font-medium text-slate-800 transition-colors leading-snug',
                  size === 'sm' ? 'text-xs' : size === 'lg' ? 'text-base' : 'text-sm',
                  disabled && 'text-slate-400'
                )}
              >
                {label}
              </span>
            )}
            {description && (
              <span
                className={cn(
                  'text-slate-500 text-xs mt-0.5 leading-normal',
                  disabled && 'text-slate-400'
                )}
              >
                {description}
              </span>
            )}
          </label>
        )}
      </div>
    );
  }
);

Switch.displayName = 'Switch';

// ============================================================================
// TYPES & INTERFACES
// ============================================================================
export type { SwitchProps } from '../../../../types/ui/field/switch.types';
